  for (let x = 57; x <= 76; x += 3) b.addProp('brazier', x, 42.2, { collide: .2, seed: rng() });
  for (const [x, y] of [[57, 44], [58, 44], [76, 44], [77, 44], [57, 30], [77, 30]]) b.addProp('rubble', x, y, { collide: .5, seed: rng() });
  b.addProp('banner_dark', 60, 33, { collide: .2, seed: rng() });
  b.addProp('banner_dark', 73, 33, { collide: .2, seed: rng() });
  for (const [x, y] of [[45, 18], [48, 18], [44, 21], [48, 15]]) b.addProp('chain', x, y, { collide: 0, seed: rng(), scale: 1 });
  b.addProp('skull_pile', 67, 33, { collide: .4, seed: rng() });

  const region = finalize(b, REGION_META.drakmor);
  region.startSpawn = { x: 25 * TILE, y: 66 * TILE, facing: 'up' };
  return region;
}

function buildKansordore() {
  const b = new RegionBuilder(REGION_META.kansordore);
  const { w, h } = b;
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const n = fbm(x * .055, y * .055, 41, 4);
    const d = fbm(x * .16, y * .16, 87, 3);
    let t = TERRAIN.CELESTIAL;
    if (n > .52) t = TERRAIN.STONE;
    if (d > .66 && n > .55) t = TERRAIN.MOSS;
    const edge = Math.min(x, y, w - 1 - x, h - 1 - y);
    if (edge < 3) t = TERRAIN.VOID;
    else if (edge < 5 && fbm(x * .2, y * .2, 5, 2) > .45) t = TERRAIN.VOID;
    // chasm running north-south near the archive
    if (x > 60 && x < 65 && y > 10 && y < 68 && fbm(y * .15, 1, 9, 2) > .3) t = TERRAIN.VOID;
    // solid central island edges
    b.set(x, y, t);
  }
  b.addClearing(30, 52, 12); b.addClearing(44, 16, 12); b.addClearing(18, 38, 5);
  b.addClearing(46, 32, 5); b.addClearing(58, 50, 6); b.addClearing(30, 62, 5);
  // Paths
  b.carvePath(30, 64, 30, 58, 2); b.carvePath(30, 58, 30, 44, 2); b.carvePath(30, 44, 24, 38, 2);
  b.carvePath(30, 44, 38, 38, 2); b.carvePath(38, 38, 46, 32, 2);
  b.carvePath(30, 44, 44, 28, 2); b.carvePath(44, 28, 44, 16, 2);
  b.carvePath(30, 58, 42, 56, 2); b.carvePath(42, 56, 58, 50, 2); b.carvePath(58, 50, 44, 38, 2);
  b.carvePath(58, 50, 66, 52, 2);
  // Bridge over chasm
  for (let y = 41; y <= 48; y++) for (let x = 59; x <= 66; x++) if (b.get(x, y) === TERRAIN.VOID) b.set(x, y, TERRAIN.BRIDGE, false);
  for (let y = 48; y <= 54; y++) for (let x = 59; x <= 66; x++) if (b.get(x, y) === TERRAIN.VOID) b.set(x, y, TERRAIN.BRIDGE, false);

  // Archivo
  b.addBuilding({ x: 24, y: 46, w: 12, h: 8, type: 'archive', palette: '#c8c2ac', roof: '#8a846e', name: 'Archivo del Velo' });
  b.addBuilding({ x: 18, y: 33, w: 4, h: 4, type: 'temple_tower', palette: '#b8b29c', roof: '#847e68', name: 'Torre' });
  b.addBuilding({ x: 42, y: 12, w: 8, h: 6, type: 'summit', palette: '#d0cab4', roof: '#a49e88', name: 'Cumbre del Coro' });
  b.addBuilding({ x: 54, y: 48, w: 5, h: 4, type: 'camp', palette: '#8a8472', roof: '#5a5448', name: 'Campamento' });
  b.addBuilding({ x: 13, y: 41, w: 4, h: 3, type: 'temple_tower', palette: '#b8b29c', roof: '#847e68', name: 'Ruina' });

  b.addShrine('shrine_archivo', 'Santuario del Archivo', 30, 58);
  b.addShrine('shrine_cumbre', 'Altar de la Cumbre', 44, 22);
  b.addShrine('shrine_camp', 'Fogata del Campamento', 58, 53);
  b.addTrigger('archivo', 30, 55, 4, { poi: true });
  b.addTrigger('eco_uno', 18, 38, 2.5, { eco: true });
  b.addTrigger('eco_dos', 46, 32, 2.5, { eco: true });
  b.addTrigger('eco_tres', 58, 50, 2.5, { eco: true });
  b.addTrigger('cumbre', 44, 19, 4, { poi: true });
  b.addTrigger('summit_arena', 44, 17, 6, { boss: 'coro_absoluto' });
  b.addInteractable('sign', 33, 59, { text: 'ARCHIVO DEL VELO\n"Lo que se olvida, aún canta."' });
  b.addInteractable('astrolabe', 34, 51, { glow: '#ffe6a0' });

  b.addNPC('veyra', 31, 54, { facing: 'down' });
  b.addNPC('sel', 27, 54, { facing: 'down' });
  b.addNPC('kael_camp', 57, 54, { facing: 'down', hidden: true });

  b.addSpawner('k_cent1', 'centinela_celeste', 38, 47, 2, 5);
  b.addSpawner('k_cent2', 'centinela_celeste', 50, 40, 2, 5);
  b.addSpawner('k_cent3', 'centinela_celeste', 24, 26, 2, 4);
  b.addSpawner('k_ser1', 'serafin_menor', 58, 38, 3, 5);
  b.addSpawner('k_ser2', 'serafin_menor', 63, 30, 2, 4);
  b.addSpawner('k_sombra1', 'sombra_velo', 66, 55, 3, 5);
  b.addSpawner('k_sombra2', 'sombra_velo', 16, 50, 2, 4);
  b.addSpawner('k_obs1', 'obsidiana_viva', 52, 62, 2, 4);

  [['eco', 18, 40], ['eco', 46, 33], ['eco', 57, 48], ['eco', 64, 44], ['pocion_mayor', 28, 60], ['esencia', 40, 23],
   ['eco', 48, 20], ['eco', 21, 44], ['esencia', 56, 32]].forEach(([it, x, y], i) => b.addPickup('kan_pick_' + i, it, x, y));
  b.addPickup('kan_chest_1', 'placa_celestial', 68, 57, 1, 'chest');
  b.addPickup('kan_chest_2', 'elixir', 50, 25, 1, 'chest');
  b.addPickup('kan_chest_3', 'capa_aurora', 44, 13, 1, 'chest');

  const rng = b.rng;
  for (let i = 0; i < 180; i++) {
    const x = 4 + rng() * (w - 8), y = 4 + rng() * (h - 8);
    if (b.nearPath(x, y, 1) || b.nearClearing(x, y, 0) || b.isSolid(x, y) || b.propMask[idx(Math.floor(x), Math.floor(y), w)]) continue;
    const tx = Math.floor(x), ty = Math.floor(y);
    b.propMask[idx(tx, ty, w)] = 1;
    b.addProp(rng() < .6 ? 'silver_tree' : 'crystal', tx + .5, ty + .5, { collide: .42, scale: .75 + rng() * .65, seed: rng() });
  }
  for (let i = 0; i < 120; i++) {
    const x = 4 + rng() * (w - 8), y = 4 + rng() * (h - 8);
    if (b.isSolid(x, y) || b.nearPath(x, y, 0)) continue;
    b.addProp(rng() < .5 ? 'crystal_small' : 'marble_rock', Math.floor(x), Math.floor(y), { collide: rng() < .3 ? .3 : 0, scale: .6 + rng() * .6, seed: rng() });
  }
  for (let i = 0; i < 80; i++) {
    const x = 4 + rng() * (w - 8), y = 4 + rng() * (h - 8);
    if (b.isSolid(x, y) || b.nearPath(x, y, 0)) continue;
    b.addProp('star_flower', Math.floor(x), Math.floor(y), { seed: rng(), color: rng() < .5 ? '#ffe8a0' : '#c8c0ff' });
  }
  for (const [x, y] of [[36, 44], [36, 57], [23, 59], [44, 52], [26, 44], [32, 63]]) b.addProp('pillar', x, y, { collide: .55, scale: 1 + rng() * .3, seed: rng() });
  for (const [x, y] of [[30, 56], [46, 25], [18, 42], [58, 48]]) b.addProp('floating_rune', x, y, { collide: 0, seed: rng(), scale: 1 });
  for (const [x, y] of [[40, 19], [49, 19], [40, 14], [49, 14]]) b.addProp('celestial_pillar', x, y, { collide: .6, scale: 1.1, seed: rng() });
  b.addProp('throne', 44, 14.2, { collide: .8, seed: rng() });

  const region = finalize(b, REGION_META.kansordore);
  region.startSpawn = { x: 30 * TILE, y: 62 * TILE, facing: 'up' };
  return region;
}

function finalize(b, meta) {
  // Add building colliders to collider grid
  for (const bd of b.buildings) {
    if (!bd.collider) continue;
    const c = bd.collider;
    const tx = Math.floor((c.x + c.w / 2) / TILE), ty = Math.floor((c.y + c.h / 2) / TILE);
    const key = `${tx},${ty}`;
    const arr = b.colliderGrid.get(key) || [];
    arr.push({ x: c.x, y: c.y, r: 0, rect: { x: c.x, y: c.y, w: c.w, h: c.h } });
    b.colliderGrid.set(key, arr);
  }
  return {
    ...meta,
    tiles: b.tiles, solid: b.solid, pathMask: b.pathMask,
    props: b.props, buildings: b.buildings, npcs: b.npcs, spawners: b.spawners,
    pickups: b.pickups, interactables: b.interactables, triggers: b.triggers, shrines: b.shrines,
    colliderGrid: b.colliderGrid || new Map(),
    widthPx: b.w * TILE, heightPx: b.h * TILE,
    tileW: b.w, tileH: b.h
  };
}

const cache = {};
export function getRegion(id) {
  if (!cache[id]) {
    if (id === 'valdoria') cache[id] = buildValdoria();
    else if (id === 'drakmor') cache[id] = buildDrakmor();
    else if (id === 'kansordore') cache[id] = buildKansordore();
    else throw new Error('Región desconocida: ' + id);
  }
  return cache[id];
}

export function tileAt(region, px, py) {
  const x = Math.floor(px / TILE), y = Math.floor(py / TILE);
  if (x < 0 || y < 0 || x >= region.tileW || y >= region.tileH) return TERRAIN.CLIFF;
  return region.tiles[y * region.tileW + x];
}

export function tileSolidAt(region, px, py) {
  const x = Math.floor(px / TILE), y = Math.floor(py / TILE);
  if (x < 0 || y < 0 || x >= region.tileW || y >= region.tileH) return true;
  return !!region.solid[y * region.tileW + x];
}

export function collidersNear(region, x, y, r = 2) {
  const out = [];
  const cx = Math.floor(x / TILE), cy = Math.floor(y / TILE);
  for (let yy = cy - 2; yy <= cy + 2; yy++) for (let xx = cx - 2; xx <= cx + 2; xx++) {
    const arr = region.colliderGrid.get(`${xx},${yy}`);
    if (arr) out.push(...arr);
  }
  return out;
}

export function canStand(region, x, y, r = 13) {
  for (const [dx, dy] of [[-r, 0], [r, 0], [0, -r], [0, r], [0, 0]]) {
    if (tileSolidAt(region, x + dx, y + dy)) return false;
  }
  for (const c of collidersNear(region, x, y)) {
    if (c.rect) {
      const nx = clamp(x, c.rect.x, c.rect.x + c.rect.w), ny = clamp(y, c.rect.y, c.rect.y + c.rect.h);
      if ((x - nx) ** 2 + (y - ny) ** 2 < r * r) return false;
    } else if ((x - c.x) ** 2 + (y - c.y) ** 2 < (c.r + r * .75) ** 2) return false;
  }
  return true;
}

export function pointInWater(region, x, y) {
  const t = tileAt(region, x, y);
  return t === TERRAIN.WATER;
}

import { TILE, TERRAIN } from '../world/regions.js';
import { hash2, rgba, shade } from '../core/utils.js';

const CHUNK = 10;
const cache = new WeakMap();

function paletteOf(region) { return region.palette; }

function tileBase(ctx, region, t, px, py, tx, ty) {
  const p = paletteOf(region);
  const h = hash2(tx, ty, region.seed);
  const h2 = hash2(tx, ty, region.seed + 77);
  switch (t) {
    case TERRAIN.GRASS: {
      const g = ctx.createLinearGradient(px, py, px, py + TILE);
      g.addColorStop(0, h > .5 ? p.grass : p.grass2);
      g.addColorStop(1, h2 > .5 ? shade(p.grass, -.06) : p.grass);
      ctx.fillStyle = g; ctx.fillRect(px, py, TILE, TILE);
      // soft patches
      for (let i = 0; i < 3; i++) {
        const a = hash2(tx * 3 + i, ty, region.seed + i);
        ctx.fillStyle = rgba(i % 2 ? p.grass2 : p.key, .13);
        ctx.beginPath(); ctx.ellipse(px + a * TILE, py + hash2(tx, ty * 4 + i, region.seed) * TILE, 9 + a * 12, 5 + a * 8, a * 3, 0, 6.3); ctx.fill();
      }
      // blades
      const blades = 2 + Math.floor(h * 4);
      for (let i = 0; i < blades; i++) {
        const bx = px + hash2(tx * 7 + i, ty * 3, region.seed) * TILE;
        const by = py + hash2(tx, ty * 9 + i, region.seed) * TILE;
        ctx.strokeStyle = rgba(i % 2 ? shade(p.grass, .18) : shade(p.grass, -.16), .5);
        ctx.lineWidth = .9;
        ctx.beginPath(); ctx.moveTo(bx, by); ctx.quadraticCurveTo(bx + 2, by - 4, bx + (h > .5 ? 3 : -3), by - 6 - h * 3); ctx.stroke();
      }
      if (h2 > .9) {
        const fx = px + 10 + h * 26, fy = py + 12 + h2 * 24;
        ctx.fillStyle = region.id === 'kansordore' ? '#f4e8b0' : (h > .45 ? '#f2e6a0' : '#d8b8ea');
        for (let k = 0; k < 5; k++) { const a = k / 5 * 6.28; ctx.beginPath(); ctx.arc(fx + Math.cos(a) * 2.1, fy + Math.sin(a) * 2.1, 1.3, 0, 6.3); ctx.fill(); }
        ctx.fillStyle = '#fff8d8'; ctx.beginPath(); ctx.arc(fx, fy, 1, 0, 6.3); ctx.fill();
      }
      break;
    }
    case TERRAIN.MOSS: {
      const g = ctx.createLinearGradient(px, py, px, py + TILE);
      g.addColorStop(0, p.moss); g.addColorStop(1, shade(p.moss, -.12));
      ctx.fillStyle = g; ctx.fillRect(px, py, TILE, TILE);
      for (let i = 0; i < 5; i++) {
        const a = hash2(tx * 11 + i, ty * 5, region.seed);
        ctx.fillStyle = rgba(i % 2 ? '#7fa06a' : '#2f4a36', .2);
        ctx.beginPath(); ctx.arc(px + a * TILE, py + hash2(tx * 3, ty * 7 + i, region.seed) * TILE, 2 + a * 4, 0, 6.3); ctx.fill();
      }
      ctx.strokeStyle = rgba('#203c2b', .22); ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(px + 4, py + h * TILE); ctx.quadraticCurveTo(px + 22, py + h2 * TILE, px + 44, py + h * TILE); ctx.stroke();
      break;
    }
    case TERRAIN.DIRT: {
      ctx.fillStyle = p.path; ctx.fillRect(px, py, TILE, TILE);
      for (let i = 0; i < 8; i++) {
        const a = hash2(tx * 13 + i, ty * 7, region.seed), b = hash2(tx * 5, ty * 11 + i, region.seed);
        ctx.fillStyle = rgba(i % 3 ? p.path2 : shade(p.path, .18), .4);
        ctx.beginPath(); ctx.arc(px + a * TILE, py + b * TILE, .8 + a * 2.2, 0, 6.3); ctx.fill();
      }
      if (h > .92) { ctx.fillStyle = rgba('#6b6153', .55); ctx.beginPath(); ctx.ellipse(px + 22, py + 30, 4, 2.5, .4, 0, 6.3); ctx.fill(); }
      break;
    }
    case TERRAIN.WATER: {
      const g = ctx.createLinearGradient(px, py, px + TILE, py + TILE);
      g.addColorStop(0, p.water); g.addColorStop(1, p.water2);
      ctx.fillStyle = g; ctx.fillRect(px, py, TILE, TILE);
      ctx.strokeStyle = 'rgba(220,245,255,.24)'; ctx.lineWidth = 1;
      for (let i = 0; i < 2; i++) {
        const yy = py + 12 + i * 17 + h * 8;
        ctx.beginPath(); ctx.moveTo(px + 5 + h * 10, yy); ctx.quadraticCurveTo(px + 22, yy - 3, px + 42, yy + 1); ctx.stroke();
      }
      ctx.fillStyle = 'rgba(255,255,255,.10)';
      ctx.beginPath(); ctx.ellipse(px + 12 + h * 24, py + 30, 9, 2, 0, 0, 6.3); ctx.fill();
      break;
    }
    case TERRAIN.LAVA: {
      const g = ctx.createRadialGradient(px + TILE * .5, py + TILE * .5, 2, px + TILE * .5, py + TILE * .5, TILE * .8);
      g.addColorStop(0, '#ffb24d'); g.addColorStop(.55, '#d94a25'); g.addColorStop(1, '#6e1a12');
      ctx.fillStyle = g; ctx.fillRect(px, py, TILE, TILE);
      ctx.strokeStyle = 'rgba(50,10,8,.55)'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(px + h * 40, py); ctx.lineTo(px + h2 * 30 + 8, py + TILE); ctx.stroke();
      ctx.fillStyle = 'rgba(255,230,150,.5)';
      ctx.beginPath(); ctx.ellipse(px + 20 + h * 12, py + 26, 4, 1.4, .3, 0, 6.3); ctx.fill();
      break;
    }
    case TERRAIN.ASH: {
      ctx.fillStyle = p.grass; ctx.fillRect(px, py, TILE, TILE);
      ctx.fillStyle = rgba(p.grass2, .55);
      ctx.beginPath(); ctx.ellipse(px + 12 + h * 26, py + 18 + h2 * 20, 9, 4, h * 3, 0, 6.3); ctx.fill();
      for (let i = 0; i < 4; i++) {
        ctx.fillStyle = rgba(i % 2 ? '#6a5c50' : '#2f2826', .35);
        ctx.beginPath(); ctx.arc(px + hash2(tx * 9 + i, ty * 3, region.seed) * TILE, py + hash2(tx, ty * 5 + i, region.seed) * TILE, 1 + i * .4, 0, 6.3); ctx.fill();
      }
      ctx.strokeStyle = 'rgba(30,22,22,.28)'; ctx.lineWidth = 1;
      if (h > .6) { ctx.beginPath(); ctx.moveTo(px + 6, py + h2 * TILE); ctx.lineTo(px + 28, py + h * 30); ctx.lineTo(px + 44, py + 20 + h2 * 22); ctx.stroke(); }
      break;
    }
    case TERRAIN.CELESTIAL: {
      const g = ctx.createLinearGradient(px, py, px, py + TILE);
      g.addColorStop(0, p.grass); g.addColorStop(1, p.grass2);
      ctx.fillStyle = g; ctx.fillRect(px, py, TILE, TILE);
      for (let i = 0; i < 4; i++) {
        ctx.fillStyle = rgba(i % 2 ? '#a0a48c' : '#6c7064', .18);
        ctx.beginPath(); ctx.ellipse(px + hash2(tx * 8 + i, ty * 2, region.seed) * TILE, py + hash2(tx, ty * 6 + i, region.seed) * TILE, 4 + h * 6, 2 + h2 * 3, h * 4, 0, 6.3); ctx.fill();
      }
      if (h > .9) { ctx.strokeStyle = 'rgba(255,245,210,.5)'; ctx.lineWidth = .8; ctx.beginPath(); ctx.arc(px + 24, py + 24, 3, 0, 6.3); ctx.stroke(); }
      break;
    }
    case TERRAIN.STONE: {
      ctx.fillStyle = p.stone; ctx.fillRect(px, py, TILE, TILE);
      ctx.fillStyle = rgba(shade(p.stone, -.14), .5);
      ctx.beginPath(); ctx.ellipse(px + 14 + h * 20, py + 16 + h2 * 18, 10, 6, h * 3, 0, 6.3); ctx.fill();
      ctx.strokeStyle = 'rgba(40,38,42,.25)'; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(px + 4, py + 12 + h * 22); ctx.lineTo(px + 20, py + 20 + h2 * 12); ctx.lineTo(px + 30, py + 34); ctx.stroke();
      if (h2 > .7) { ctx.fillStyle = 'rgba(255,255,255,.12)'; ctx.beginPath(); ctx.ellipse(px + 20, py + 14, 7, 2, .4, 0, 6.3); ctx.fill(); }
      break;
    }
    case TERRAIN.BRIDGE: {
      // water/void underneath
      const under = region.id === 'drakmor' ? TERRAIN.LAVA : (region.id === 'kansordore' ? TERRAIN.VOID : TERRAIN.WATER);
      tileBase(ctx, region, under, px, py, tx, ty);
      // wooden planks
      ctx.save();
      const vertical = (Math.abs(tx - 83) < 7) || region.id === 'drakmor';
      ctx.translate(px + TILE / 2, py + TILE / 2);
      if (!vertical) ctx.rotate(Math.PI / 2);
      ctx.fillStyle = 'rgba(20,14,10,.25)'; ctx.fillRect(-TILE / 2 + 3, -TILE / 2 + 4, TILE - 2, TILE - 2);
      for (let i = 0; i < 6; i++) {
        ctx.fillStyle = i % 2 ? '#7a5c3e' : '#6a4e34';
        ctx.fillRect(-TILE / 2, -TILE / 2 + i * 8, TILE, 7);
        ctx.fillStyle = 'rgba(255,230,180,.08)'; ctx.fillRect(-TILE / 2, -TILE / 2 + i * 8, TILE, 1);
      }
      ctx.fillStyle = '#4a3524'; ctx.fillRect(-TILE / 2, -TILE / 2, 5, TILE); ctx.fillRect(TILE / 2 - 5, -TILE / 2, 5, TILE);
      ctx.restore();
      break;
    }
    case TERRAIN.CLIFF: {
      const g = ctx.createLinearGradient(px, py, px, py + TILE);
      g.addColorStop(0, '#4b4644'); g.addColorStop(.5, p.cliff); g.addColorStop(1, '#242124');
      ctx.fillStyle = g; ctx.fillRect(px, py, TILE, TILE);
      ctx.strokeStyle = 'rgba(15,12,14,.45)'; ctx.lineWidth = 2;
      for (let i = 0; i < 2; i++) {
        ctx.beginPath(); ctx.moveTo(px + h * TILE, py); ctx.lineTo(px + 8 + h2 * 30, py + 20 + i * 16); ctx.lineTo(px + 30 + h * 16, py + TILE); ctx.stroke();
      }
      ctx.fillStyle = 'rgba(255,240,220,.08)'; ctx.fillRect(px, py, TILE, 3);
      break;
    }
    case TERRAIN.VOID: {
      const g = ctx.createRadialGradient(px + TILE / 2, py + TILE / 2, 1, px + TILE / 2, py + TILE / 2, TILE);
      g.addColorStop(0, '#101426'); g.addColorStop(1, '#05060d');
      ctx.fillStyle = g; ctx.fillRect(px, py, TILE, TILE);
      if (h > .55) { ctx.fillStyle = rgba('#dfe8ff', .3 + h * .5); ctx.beginPath(); ctx.arc(px + h2 * TILE, py + h * TILE, h > .9 ? 1.6 : .9, 0, 6.3); ctx.fill(); }
      if (h2 > .8) { ctx.fillStyle = 'rgba(180,170,255,.15)'; ctx.beginPath(); ctx.arc(px + 24, py + 20, 7, 0, 6.3); ctx.fill(); }
      break;
    }
    default: ctx.fillStyle = '#333'; ctx.fillRect(px, py, TILE, TILE);
  }
}

export function getChunk(region, cx, cy) {
  let map = cache.get(region);
  if (!map) { map = new Map(); cache.set(region, map); }
  const key = cx + ',' + cy;
  if (map.has(key)) return map.get(key);
  const c = document.createElement('canvas');
  c.width = CHUNK * TILE; c.height = CHUNK * TILE;
  const ctx = c.getContext('2d');
  for (let y = 0; y < CHUNK; y++) for (let x = 0; x < CHUNK; x++) {
    const tx = cx * CHUNK + x, ty = cy * CHUNK + y;
    if (tx >= region.tileW || ty >= region.tileH) continue;
    const t = region.tiles[ty * region.tileW + tx];
    tileBase(ctx, region, t, x * TILE, y * TILE, tx, ty);
    // edge shadow for solid tiles (cliffs/water)
    if ((t === TERRAIN.CLIFF || t === TERRAIN.VOID) && region.tiles[ty * region.tileW + Math.max(0, tx - 1)] !== t) {
      const g = ctx.createLinearGradient(x * TILE, 0, x * TILE + 10, 0);
      g.addColorStop(0, 'rgba(0,0,0,.4)'); g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = g; ctx.fillRect(x * TILE, y * TILE, 10, TILE);
    }
  }
  map.set(key, c);
  return c;
}

export function drawTerrain(ctx, region, camera, time) {
  const cs = CHUNK * TILE;
  const x0 = Math.floor(camera.x / cs), x1 = Math.floor((camera.x + camera.w) / cs);
  const y0 = Math.floor(camera.y / cs), y1 = Math.floor((camera.y + camera.h) / cs);
  for (let cy = y0; cy <= y1; cy++) for (let cx = x0; cx <= x1; cx++) {
    if (cx < 0 || cy < 0 || cx * CHUNK >= region.tileW || cy * CHUNK >= region.tileH) continue;
    ctx.drawImage(getChunk(region, cx, cy), cx * cs - camera.x, cy * cs - camera.y);
  }
  // Animated overlays only on visible tiles
  const tx0 = Math.max(0, Math.floor(camera.x / TILE)), tx1 = Math.min(region.tileW - 1, Math.floor((camera.x + camera.w) / TILE));
  const ty0 = Math.max(0, Math.floor(camera.y / TILE)), ty1 = Math.min(region.tileH - 1, Math.floor((camera.y + camera.h) / TILE));
  for (let ty = ty0; ty <= ty1; ty++) for (let tx = tx0; tx <= tx1; tx++) {
    const t = region.tiles[ty * region.tileW + tx];
    const px = tx * TILE - camera.x, py = ty * TILE - camera.y;
    if (t === TERRAIN.WATER) {
      const ph = time * .8 + (tx * .8 + ty * 1.2);
      ctx.strokeStyle = 'rgba(225,250,255,.2)'; ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(px + 6, py + 14 + Math.sin(ph) * 3);
      ctx.quadraticCurveTo(px + 24, py + 10 + Math.sin(ph + 1) * 3, px + 42, py + 15 + Math.sin(ph + 2) * 2);
      ctx.stroke();
      ctx.fillStyle = 'rgba(255,255,255,.12)';
      ctx.beginPath(); ctx.ellipse(px + 24 + Math.sin(ph * .6) * 8, py + 32, 8, 1.5, 0, 0, 6.3); ctx.fill();
    } else if (t === TERRAIN.LAVA) {
      const ph = time * 1.4 + tx * .5 + ty * .8;
      const glow = .18 + Math.sin(ph) * .06;
      ctx.fillStyle = `rgba(255,160,60,${glow})`;
      ctx.beginPath(); ctx.ellipse(px + 24 + Math.sin(ph * .4) * 10, py + 24 + Math.cos(ph * .3) * 8, 12, 4, 0, 0, 6.3); ctx.fill();
      if (Math.sin(ph * .7) > .92) {
        ctx.fillStyle = 'rgba(255,230,150,.7)';
        ctx.beginPath(); ctx.arc(px + 16 + (ph * 13) % 20, py + 30, 1.5, 0, 6.3); ctx.fill();
      }
    } else if (t === TERRAIN.VOID) {
      const ph = time * .5 + tx * .3 + ty * .7;
      if (Math.sin(ph) > .95) { ctx.fillStyle = 'rgba(220,225,255,.5)'; ctx.beginPath(); ctx.arc(px + 10 + (tx * 17) % 28, py + 12 + (ty * 23) % 26, 1, 0, 6.3); ctx.fill(); }
    }
  }
}

export function drawWaterGlow(ctx, region, camera, player, time) {
  // subtle animated caustics near the player for life
  const p = region.palette;
  const x = player.x - camera.x, y = player.y - camera.y;
  const g = ctx.createRadialGradient(x, y, 10, x, y, 180);
  g.addColorStop(0, rgba(p.glow, .045)); g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g; ctx.fillRect(x - 180, y - 180, 360, 360);
}

import { TILE } from '../world/regions.js';
import { hash2, rgba, shade } from '../core/utils.js';

const OUT = 'rgba(20,16,20,.85)';

function shadow(ctx, x, y, rx, ry, a = .32) {
  const g = ctx.createRadialGradient(x, y, 1, x, y, rx);
  g.addColorStop(0, `rgba(5,8,10,${a})`); g.addColorStop(1, 'rgba(5,8,10,0)');
  ctx.save(); ctx.translate(x, y); ctx.scale(1, ry / rx); ctx.fillStyle = g; ctx.beginPath(); ctx.arc(0, 0, rx, 0, 6.3); ctx.fill(); ctx.restore();
}

function glow(ctx, x, y, r, color, alpha = .25) {
  const g = ctx.createRadialGradient(x, y, 1, x, y, r);
  g.addColorStop(0, rgba(color, alpha)); g.addColorStop(.5, rgba(color, alpha * .4)); g.addColorStop(1, rgba(color, 0));
  ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y, r, 0, 6.3); ctx.fill();
}

function poly(ctx, pts, fill, stroke = null, lw = 1.5) {
  ctx.beginPath(); ctx.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
  ctx.closePath();
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
}

function leafCluster(ctx, x, y, r, c1, c2, outline = true) {
  ctx.beginPath(); ctx.arc(x, y, r, 0, 6.3);
  const g = ctx.createRadialGradient(x - r * .35, y - r * .4, 1, x, y, r);
  g.addColorStop(0, c1); g.addColorStop(.75, c2); g.addColorStop(1, shade(c2, -.2));
  ctx.fillStyle = g; ctx.fill();
  if (outline) { ctx.strokeStyle = 'rgba(16,28,20,.45)'; ctx.lineWidth = 1.2; ctx.stroke(); }
}

function drawTree(ctx, p, x, y, s, time) {
  const sway = Math.sin(time * 1.1 + p.seed * 12) * 2.2 * s;
  shadow(ctx, x, y + 2, 26 * s, 8 * s, .3);
  const trunkTop = -50 * s;
  ctx.beginPath();
  ctx.moveTo(x - 6 * s, y);
  ctx.quadraticCurveTo(x - 4 * s, y - 26 * s, x - 2 * s + sway * .5, y + trunkTop);
  ctx.lineTo(x + 3 * s + sway * .5, y + trunkTop);
  ctx.quadraticCurveTo(x + 5 * s, y - 26 * s, x + 7 * s, y);
  ctx.closePath();
  const tg = ctx.createLinearGradient(x - 6 * s, y, x + 7 * s, y);
  tg.addColorStop(0, '#3c2c22'); tg.addColorStop(.45, '#6a4a32'); tg.addColorStop(1, '#33241d');
  ctx.fillStyle = tg; ctx.fill();
  ctx.strokeStyle = 'rgba(30,20,16,.35)'; ctx.lineWidth = 1; ctx.stroke();
  ctx.strokeStyle = 'rgba(255,220,170,.08)'; ctx.beginPath(); ctx.moveTo(x - 1 * s, y - 8 * s); ctx.quadraticCurveTo(x - 2 * s, y - 24 * s, x + sway * .4, y - 38 * s); ctx.stroke();
  // roots
  ctx.strokeStyle = '#3a2a20'; ctx.lineWidth = 2 * s;
  ctx.beginPath(); ctx.moveTo(x - 3 * s, y - 2); ctx.lineTo(x - 12 * s, y + 2); ctx.moveTo(x + 4 * s, y - 2); ctx.lineTo(x + 13 * s, y + 3); ctx.stroke();
  // canopy
  const cx = x + sway, cy = y + trunkTop - 4 * s;
  leafCluster(ctx, cx - 18 * s, cy + 8 * s, 20 * s, '#79a85e', '#3f6b42');
  leafCluster(ctx, cx + 18 * s, cy + 4 * s, 21 * s, '#82b064', '#456f44');
  leafCluster(ctx, cx - 3 * s, cy - 12 * s, 25 * s, '#93bf6c', '#4d7a48');
  leafCluster(ctx, cx + 10 * s, cy - 20 * s, 16 * s, '#a0c976', '#527e4a');
  leafCluster(ctx, cx - 22 * s, cy - 13 * s, 14 * s, '#8bb868', '#486f43');
  // highlights
  ctx.fillStyle = 'rgba(220,245,170,.16)';
  ctx.beginPath(); ctx.ellipse(cx - 8 * s, cy - 21 * s, 12 * s, 6 * s, -.5, 0, 6.3); ctx.fill();
  ctx.beginPath(); ctx.ellipse(cx + 21 * s, cy - 6 * s, 8 * s, 3.5 * s, .3, 0, 6.3); ctx.fill();
}

function drawPine(ctx, p, x, y, s, time) {
  const sway = Math.sin(time * 1.3 + p.seed * 9) * 1.2 * s;
  shadow(ctx, x, y + 2, 20 * s, 7 * s, .28);
  ctx.fillStyle = '#3a2a20';
  ctx.fillRect(x - 3 * s, y - 18 * s, 6 * s, 18 * s);
  for (let i = 0; i < 4; i++) {
    const yy = y - 16 * s - i * 16 * s;
    const w = (26 - i * 5) * s;
    const h = 25 * s;
    poly(ctx, [[x - w + sway * (i / 4), yy], [x, yy - h], [x + w + sway * (i / 4), yy], [x, yy + 8 * s]], i % 2 ? '#3f6b4b' : '#487654', 'rgba(20,40,30,.3)', 1);
  }
  ctx.fillStyle = 'rgba(190,230,180,.13)';
  ctx.beginPath(); ctx.ellipse(x - 5 * s, y - 52 * s, 7 * s, 12 * s, -.2, 0, 6.3); ctx.fill();
}

function drawBush(ctx, p, x, y, s) {
  shadow(ctx, x, y + 1, 14 * s, 4 * s, .24);
  leafCluster(ctx, x - 7 * s, y - 7 * s, 9 * s, '#7fa865', '#3f6a42');
  leafCluster(ctx, x + 6 * s, y - 8 * s, 10 * s, '#86b06a', '#456f45');
  leafCluster(ctx, x, y - 14 * s, 11 * s, '#95bf72', '#4a7548');
  ctx.fillStyle = 'rgba(255,220,240,.5)';
  if (p.seed > .5) { ctx.beginPath(); ctx.arc(x + 3 * s, y - 16 * s, 1.5, 0, 6.3); ctx.fill(); }
}

function drawRock(ctx, p, x, y, s, region) {
  shadow(ctx, x, y + 1, 15 * s, 5 * s, .3);
  poly(ctx, [[x - 12 * s, y], [x - 13 * s, y - 10 * s], [x - 6 * s, y - 17 * s], [x + 5 * s, y - 16 * s], [x + 12 * s, y - 7 * s], [x + 10 * s, y]], '#6e6a64', OUT, 1.1);
  poly(ctx, [[x - 12 * s, y - 10 * s], [x - 5 * s, y - 16 * s], [x + 1 * s, y - 10 * s], [x - 4 * s, y - 4 * s]], '#8a857c', null);
  ctx.fillStyle = 'rgba(255,255,255,.1)'; ctx.beginPath(); ctx.ellipse(x + 1 * s, y - 12 * s, 4 * s, 2 * s, .2, 0, 6.3); ctx.fill();
  if (region.id === 'kansordore') { ctx.strokeStyle = 'rgba(255,235,170,.45)'; ctx.lineWidth = .8; ctx.beginPath(); ctx.moveTo(x - 4 * s, y - 12 * s); ctx.lineTo(x + 1 * s, y - 7 * s); ctx.lineTo(x + 5 * s, y - 9 * s); ctx.stroke(); }
}

function drawFlower(ctx, p, x, y, s, time) {
  const sway = Math.sin(time * 1.7 + p.seed * 8) * 1.2;
  ctx.strokeStyle = 'rgba(40,70,40,.6)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(x, y); ctx.quadraticCurveTo(x + sway, y - 5 * s, x + sway, y - 9 * s); ctx.stroke();
  const c = p.color || '#f2e6a0';
  for (let i = 0; i < 5; i++) {
    const a = i / 5 * 6.28 + p.seed;
    ctx.fillStyle = c;
    ctx.beginPath(); ctx.ellipse(x + sway + Math.cos(a) * 2.5, y - 9 * s + Math.sin(a) * 2.5, 1.7, 1.1, a, 0, 6.3); ctx.fill();
  }
  ctx.fillStyle = '#fff8d8'; ctx.beginPath(); ctx.arc(x + sway, y - 9 * s, 1.2, 0, 6.3); ctx.fill();
}

function drawColumn(ctx, p, x, y, s, time) {
  shadow(ctx, x, y + 1, 14 * s, 5 * s, .32);
  const h = 54 * s;
  ctx.fillStyle = '#a8a08e';
  ctx.fillRect(x - 11 * s, y - 5 * s, 22 * s, 6 * s);
  ctx.fillStyle = '#8c8474'; ctx.fillRect(x - 8 * s, y - 6 * s, 16 * s, 5 * s);
  const g = ctx.createLinearGradient(x - 8 * s, 0, x + 8 * s, 0);
  g.addColorStop(0, '#7e7768'); g.addColorStop(.4, '#b8b0a0'); g.addColorStop(.7, '#a49c8a'); g.addColorStop(1, '#756e62');
  ctx.fillStyle = g; ctx.fillRect(x - 7 * s, y - h, 14 * s, h - 4 * s);
  for (let i = -1; i <= 1; i++) { ctx.fillStyle = 'rgba(60,55,48,.22)'; ctx.fillRect(x + i * 4 * s, y - h + 4 * s, 1.2, h - 12 * s); }
  poly(ctx, [[x - 10 * s, y - h], [x + 9 * s, y - h - 4 * s], [x + 11 * s, y - h + 5 * s], [x - 11 * s, y - h + 5 * s]], '#b8b0a0', OUT, 1);
  ctx.fillStyle = 'rgba(120,160,110,.3)'; ctx.beginPath(); ctx.ellipse(x - 4 * s, y - 10 * s, 5 * s, 4 * s, 0, 0, 6.3); ctx.fill();
}

function drawDeadTree(ctx, p, x, y, s, time) {
  const sway = Math.sin(time * .9 + p.seed * 7) * 1.8;
  shadow(ctx, x, y + 1, 24 * s, 7 * s, .3);
  ctx.strokeStyle = '#2e2525'; ctx.lineCap = 'round';
  ctx.lineWidth = 7 * s; ctx.beginPath(); ctx.moveTo(x, y); ctx.quadraticCurveTo(x - 5 * s, y - 30 * s, x + 2 * s + sway, y - 58 * s); ctx.stroke();
  ctx.lineWidth = 3.4 * s;
  const branches = [[-1, 30, -22, 52], [1, 38, 24, 54], [-.6, 45, -16, 68], [.6, 48, 15, 72]];
  for (const [dir, at, ex, ey] of branches) {
    ctx.beginPath(); ctx.moveTo(x + 1 * s, y - at * s); ctx.quadraticCurveTo(x + dir * 12 * s + sway, y - at * s - 8 * s, x + ex * s + sway, y - ey * s); ctx.stroke();
  }
  ctx.strokeStyle = '#5a4740'; ctx.lineWidth = 1.2 * s;
  ctx.beginPath(); ctx.moveTo(x - 2 * s, y); ctx.quadraticCurveTo(x - 4 * s, y - 32 * s, x + 1 * s + sway, y - 56 * s); ctx.stroke();
  if (p.seed > .55) { glow(ctx, x + 12 * s, y - 48 * s, 18 * s, '#ff8a48', .05); }
}

function drawBasalt(ctx, p, x, y, s) {
  shadow(ctx, x, y + 1, 16 * s, 5 * s, .34);
  poly(ctx, [[x - 14 * s, y], [x - 9 * s, y - 22 * s], [x - 2 * s, y - 27 * s], [x + 7 * s, y - 20 * s], [x + 13 * s, y]], '#3d3436', OUT, 1.2);
  poly(ctx, [[x - 9 * s, y - 22 * s], [x - 2 * s, y - 27 * s], [x + 3 * s, y - 16 * s], [x - 4 * s, y - 9 * s]], '#514447', null);
  ctx.strokeStyle = 'rgba(255,110,50,.5)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(x - 8 * s, y - 4 * s); ctx.lineTo(x - 2 * s, y - 13 * s); ctx.lineTo(x + 4 * s, y - 10 * s); ctx.stroke();
}

function drawLavaRock(ctx, p, x, y, s, time) {
  drawBasalt(ctx, p, x, y, s);
  glow(ctx, x, y - 8 * s, 16 * s, '#ff7a30', .12 + Math.sin(time * 2 + p.seed * 8) * .04);
}

function drawCrystal(ctx, p, x, y, s, time, color = '#b8c8ff') {
  shadow(ctx, x, y + 1, 19 * s, 6 * s, .3);
  glow(ctx, x, y - 18 * s, 38 * s, color, .12);
  const shards = [[0, 46, 8], [-11, 30, 6], [10, 34, 7], [-3, 60, 4]];
  for (let i = 0; i < shards.length; i++) {
    const [ox, h, w] = shards[i];
    poly(ctx, [[x + ox * s, y], [x + (ox - w) * s, y - h * .55 * s], [x + (ox + w * .3) * s, y - h * s], [x + (ox + w) * s, y - h * .5 * s]], i % 2 ? 'rgba(150,170,255,.55)' : 'rgba(200,215,255,.6)', 'rgba(80,90,160,.6)', 1);
    poly(ctx, [[x + ox * s, y], [x + (ox - w) * s, y - h * .55 * s], [x + ox * s, y - h * .7 * s]], 'rgba(255,255,255,.24)', null);
  }
  const tw = Math.sin(time * 2.2 + p.seed * 9) > .7;
  if (tw) { ctx.fillStyle = 'rgba(255,255,255,.85)'; ctx.beginPath(); ctx.arc(x + 8 * s, y - 30 * s, 1.3, 0, 6.3); ctx.fill(); }
}

function drawSilverTree(ctx, p, x, y, s, time) {
  const sway = Math.sin(time * .9 + p.seed * 10) * 1.6;
  shadow(ctx, x, y + 1, 24 * s, 7 * s, .25);
  ctx.strokeStyle = '#d8d4c8'; ctx.lineWidth = 5 * s; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(x, y); ctx.quadraticCurveTo(x - 2 * s, y - 30 * s, x + sway, y - 54 * s); ctx.stroke();
  ctx.lineWidth = 2.4 * s;
  for (const [dx, dy] of [[-18, -50], [17, -54], [-9, -63], [8, -66]]) {
    ctx.beginPath(); ctx.moveTo(x, y - 36 * s); ctx.quadraticCurveTo(x + dx * .5, y - 44 * s, x + dx * s + sway, y + dy * s); ctx.stroke();
  }
  for (let i = 0; i < 5; i++) {
    const a = p.seed * 6 + i * 1.7;
    const bx = x + Math.cos(a) * 18 * s + sway, by = y - 54 * s + Math.sin(a) * 12 * s;
    leafCluster(ctx, bx, by, (7 + (i % 3) * 3) * s, '#f0e8ff', '#b8a8d8', false);
  }
  ctx.fillStyle = 'rgba(255,230,200,.2)';
  ctx.beginPath(); ctx.arc(x + 4 * s, y - 58 * s, 2.2 * s, 0, 6.3); ctx.fill();
}

function drawBuilding(ctx, b, cam, time) {
  const x = b.x - cam.x, y = b.y - cam.y, w = b.w, h = b.h;
  const t = b.type;
  shadow(ctx, x + w / 2, y + h - 4, w * .62, 18, .42);
  const wall = b.palette || '#8a7058', roof = b.roof || '#5a4038';
  const dark = shade(wall, -.28), light = shade(wall, .18);
  const bodyTop = y + h * .36, bodyH = h * .6;
  if (t === 'camp') {
    // tent
    poly(ctx, [[x + w * .06, y + h * .92], [x + w * .5, y + h * .18], [x + w * .94, y + h * .92]], wall, OUT, 2);
    poly(ctx, [[x + w * .5, y + h * .18], [x + w * .94, y + h * .92], [x + w * .5, y + h * .92]], dark, null);
    poly(ctx, [[x + w * .38, y + h * .92], [x + w * .5, y + h * .5], [x + w * .62, y + h * .92]], '#2a2420', null);
    glow(ctx, x + w * .5, y + h * .98, w * .5, '#ff9a50', .08);
    return;
  }
  // walls
  ctx.fillStyle = wall; ctx.fillRect(x + w * .08, bodyTop, w * .84, bodyH);
  ctx.fillStyle = 'rgba(255,255,255,.06)'; ctx.fillRect(x + w * .08, bodyTop, w * .84, 3);
  ctx.fillStyle = dark; ctx.fillRect(x + w * .08, bodyTop + bodyH - 7, w * .84, 7);
  // timber frame
  if (t === 'house' || t === 'bakery' || t === 'ruin_house' || t === 'herb') {
    ctx.strokeStyle = 'rgba(45,30,22,.55)'; ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(x + w * .08, bodyTop + 4); ctx.lineTo(x + w * .08, bodyTop + bodyH);
    ctx.moveTo(x + w * .92, bodyTop + 4); ctx.lineTo(x + w * .92, bodyTop + bodyH);
    ctx.moveTo(x + w * .08, bodyTop + bodyH * .5); ctx.lineTo(x + w * .92, bodyTop + bodyH * .5);
    ctx.moveTo(x + w * .08, bodyTop); ctx.lineTo(x + w * .3, bodyTop + bodyH * .5); ctx.lineTo(x + w * .5, bodyTop);
    ctx.stroke();
  }
  // roof
  if (t === 'fortress' || t === 'fortress_tower') {
    ctx.fillStyle = roof; ctx.fillRect(x + w * .04, y + h * .18, w * .92, h * .26);
    for (let i = 0; i < 5; i++) { ctx.fillStyle = i % 2 ? dark : roof; ctx.fillRect(x + w * .04 + i * w * .19, y + h * .1, w * .11, h * .1); }
    ctx.fillStyle = '#2a2428';
    for (let i = 0; i < 3; i++) ctx.fillRect(x + w * .18 + i * w * .24, y + h * .55, w * .09, h * .16);
  } else if (t === 'archive' || t === 'temple_tower' || t === 'summit') {
    // columned celestial structure
    ctx.fillStyle = shade(roof, -.1);
    poly(ctx, [[x - w * .04, y + h * .3], [x + w * .1, y + h * .06], [x + w * .9, y + h * .06], [x + w * 1.04, y + h * .3]], '#c8c2ae', OUT, 1.4);
    ctx.fillStyle = shade(roof, .12); ctx.fillRect(x + w * .06, y + h * .3, w * .88, h * .08);
    ctx.fillStyle = 'rgba(255,240,190,.3)'; ctx.fillRect(x + w * .12, y + h * .08, w * .76, 2);
    for (let i = 0; i < 4; i++) {
      const cx = x + w * (.14 + i * .24);
      ctx.fillStyle = '#e0dac4'; ctx.fillRect(cx, y + h * .4, w * .055, h * .48);
      ctx.fillStyle = 'rgba(80,78,70,.25)'; ctx.fillRect(cx + w * .035, y + h * .4, w * .02, h * .48);
      ctx.fillStyle = '#d0cab4'; ctx.fillRect(cx - w * .012, y + h * .86, w * .08, h * .06);
    }
    if (t === 'archive') {
      // dome
      ctx.fillStyle = '#b8b2a0';
      ctx.beginPath(); ctx.ellipse(x + w * .5, y + h * .2, w * .2, h * .16, 0, Math.PI, 0); ctx.fill();
      ctx.strokeStyle = 'rgba(255,245,210,.5)'; ctx.lineWidth = 1; ctx.stroke();
      glow(ctx, x + w * .5, y + h * .42, w * .45, '#ffe8a0', .07);
    }
  } else {
    // gable roof
    const rh = h * .44;
    poly(ctx, [[x - 6, y + h * .44], [x + w * .5, y + h * .05], [x + w + 6, y + h * .44], [x + w + 6, y + h * .54], [x - 6, y + h * .54]], roof, OUT, 1.4);
    poly(ctx, [[x + w * .5, y + h * .05], [x + w + 6, y + h * .44], [x + w * .5, y + h * .54]], 'rgba(0,0,0,.2)', null);
    // shingles
    ctx.strokeStyle = 'rgba(30,20,18,.18)'; ctx.lineWidth = 1;
    for (let i = 1; i < 4; i++) {
      const yy = y + h * .14 + i * h * .1;
      ctx.beginPath(); ctx.moveTo(x + w * .5 - w * .5 * (1 - i * .16), yy); ctx.lineTo(x + w * .5 + w * .5 * (1 - i * .16), yy); ctx.stroke();
    }
    // ridge highlight
    ctx.strokeStyle = 'rgba(255,230,190,.18)'; ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.moveTo(x + 2, y + h * .46); ctx.lineTo(x + w * .5, y + h * .08); ctx.stroke();
    if (t === 'smith' || t === 'forge' || t === 'volcano_forge' || t === 'bakery') {
      // chimney
      ctx.fillStyle = '#4a3a32'; ctx.fillRect(x + w * .72, y + h * .02, w * .09, h * .24);
      ctx.fillStyle = '#2e2422'; ctx.fillRect(x + w * .71, y + h * .02, w * .11, 4);
      for (let i = 0; i < 3; i++) {
        const ph = (time * .3 + i * .33 + b.x * .001) % 1;
        ctx.fillStyle = `rgba(180,180,190,${.09 * (1 - ph)})`;
        ctx.beginPath(); ctx.arc(x + w * .76 + Math.sin(ph * 6) * 5, y - ph * 40 + 4, 5 + ph * 9, 0, 6.3); ctx.fill();
      }
      glow(ctx, x + w * .5, y + h * .82, w * .55, '#ff9a4a', .12);
    }
  }
  // door + windows
  const doorW = w * .15, doorH = h * .27;
  ctx.fillStyle = '#2a1f1a'; ctx.fillRect(x + w * .5 - doorW / 2, y + h * .68, doorW, doorH);
  ctx.fillStyle = 'rgba(255,200,120,.55)'; ctx.fillRect(x + w * .5 - doorW * .35, y + h * .7, doorW * .7, doorH * .45);
  ctx.fillStyle = '#c8a060'; ctx.beginPath(); ctx.arc(x + w * .5 + doorW * .28, y + h * .8, 1.5, 0, 6.3); ctx.fill();
  if (t !== 'fortress' && t !== 'fortress_tower') {
    for (const wx of [.28, .72]) {
      const ww = w * .12, wh = h * .13;
      ctx.fillStyle = '#2a201c'; ctx.fillRect(x + w * wx - ww / 2, y + h * .58, ww, wh);
      ctx.fillStyle = 'rgba(255,205,130,.7)'; ctx.fillRect(x + w * wx - ww / 2 + 2, y + h * .58 + 2, ww - 4, wh - 4);
      ctx.fillStyle = 'rgba(60,40,30,.75)'; ctx.fillRect(x + w * wx - 1, y + h * .58, 2, wh); ctx.fillRect(x + w * wx - ww / 2, y + h * .58 + wh / 2, ww, 1.5);
    }
  }
  // signs
  const signData = { library: '📖', smith: '⚒', herb: '✿', bakery: '◔' };
  if (signData[t]) {
    ctx.fillStyle = '#3a2a20'; ctx.fillRect(x + w * .82, y + h * .56, 2, 16);
    ctx.fillStyle = '#c8a468'; ctx.fillRect(x + w * .82 - 8, y + h * .56, 18, 11);
    ctx.fillStyle = '#3a2a20'; ctx.font = '8px serif'; ctx.textAlign = 'center';
    ctx.fillText(signData[t], x + w * .82 + 1, y + h * .56 + 8);
  }
  // vines / rubble
  if (t === 'ruin_house') {
    ctx.fillStyle = 'rgba(40,36,32,.4)';
    ctx.beginPath(); ctx.moveTo(x + w * .65, y + h * .46); ctx.lineTo(x + w * .9, y + h * .52); ctx.lineTo(x + w * .82, y + h * .75); ctx.lineTo(x + w * .62, y + h * .6); ctx.fill();
    ctx.fillStyle = 'rgba(90,120,70,.35)';
    ctx.beginPath(); ctx.ellipse(x + w * .18, y + h * .6, w * .08, h * .1, .4, 0, 6.3); ctx.fill();
  }
  if (t === 'herb') {
    ctx.strokeStyle = '#6f9e62'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(x + w * .9, y + h * .55); ctx.quadraticCurveTo(x + w * .86, y + h * .75, x + w * .94, y + h * .85); ctx.stroke();
    for (let i = 0; i < 3; i++) { ctx.fillStyle = '#9ac47a'; ctx.beginPath(); ctx.arc(x + w * .9 + Math.sin(i * 2) * 5, y + h * (.6 + i * .07), 2.5, 0, 6.3); ctx.fill(); }
  }
  if (t === 'banner' || b.name === 'Taberna') {
    ctx.fillStyle = '#7a3a32'; ctx.fillRect(x + w * .05, y + h * .3, 2, 18);
    poly(ctx, [[x + w * .05 + 2, y + h * .31], [x + w * .05 + 14, y + h * .33], [x + w * .05 + 12, y + h * .4], [x + w * .05 + 2, y + h * .38]], '#9a4a3a', null);
  }
}

function drawProp(ctx, p, cam, time, region) {
  const x = p.x - cam.x, y = p.y - cam.y;
  if (x < -160 || y < -220 || x > cam.w + 160 || y > cam.h + 120) return;
  const s = p.scale || 1;
  switch (p.type) {
    case 'tree': drawTree(ctx, p, x, y, s, time); break;
    case 'pine': drawPine(ctx, p, x, y, s, time); break;
    case 'bush': drawBush(ctx, p, x, y, s); break;
    case 'rock': drawRock(ctx, p, x, y, s, region); break;
    case 'flower': drawFlower(ctx, p, x, y, s, time); break;
    case 'column': drawColumn(ctx, p, x, y, s, time); break;
    case 'dead_tree': drawDeadTree(ctx, p, x, y, s, time); break;
    case 'basalt': drawBasalt(ctx, p, x, y, s); break;
    case 'lava_rock': drawLavaRock(ctx, p, x, y, s, time); break;
    case 'crystal':
    case 'crystal_small': drawCrystal(ctx, p, x, y, s * (p.type === 'crystal_small' ? .65 : 1), time, region.id === 'kansordore' ? '#c8c0ff' : '#b8d8ff'); break;
    case 'silver_tree': drawSilverTree(ctx, p, x, y, s, time); break;
    case 'marble_rock': drawRock(ctx, p, x, y, s, region); break;
    case 'star_flower': drawFlower(ctx, p, x, y, s, time); break;
    case 'rubble': {
      shadow(ctx, x, y + 1, 15 * s, 4 * s, .25);
      ctx.fillStyle = '#4a4040'; ctx.beginPath(); ctx.ellipse(x, y - 2, 13 * s, 4 * s, .3, 0, 6.3); ctx.fill();
      for (let i = 0; i < 3; i++) { ctx.fillStyle = i % 2 ? '#5a5050' : '#3a3232'; ctx.fillRect(x - 8 * s + i * 6 * s, y - 6 * s - i * 2, 5 * s, 4 * s); }
      break;
    }
    case 'ember_vent': {
      ctx.fillStyle = '#2a1e1e'; ctx.beginPath(); ctx.ellipse(x, y, 10 * s, 4 * s, 0, 0, 6.3); ctx.fill();
      glow(ctx, x, y - 3, 22 * s, '#ff7a30', .16 + Math.sin(time * 3 + p.seed * 5) * .04);
      if (Math.sin(time * 2.2 + p.seed * 9) > .7) { ctx.fillStyle = 'rgba(255,200,120,.8)'; ctx.beginPath(); ctx.arc(x + 2 * s, y - 8 * s, 1.2, 0, 6.3); ctx.fill(); }
      break;
    }
    case 'bone': {
      ctx.strokeStyle = '#b8b0a0'; ctx.lineWidth = 2.2 * s; ctx.lineCap = 'round';
      ctx.beginPath(); ctx.moveTo(x - 8 * s, y); ctx.lineTo(x + 8 * s, y - 3 * s); ctx.stroke();
      ctx.fillStyle = '#cfc6b4'; ctx.beginPath(); ctx.arc(x - 9 * s, y, 2.5 * s, 0, 6.3); ctx.arc(x + 9 * s, y - 3 * s, 2.5 * s, 0, 6.3); ctx.fill();
      break;
    }
    case 'brazier': {
      shadow(ctx, x, y + 1, 12 * s, 3 * s, .3);
      ctx.fillStyle = '#2a2424'; ctx.fillRect(x - 2 * s, y - 16 * s, 4 * s, 16 * s);
      ctx.fillStyle = '#4a3e3a'; ctx.beginPath(); ctx.ellipse(x, y - 16 * s, 10 * s, 4 * s, 0, 0, 6.3); ctx.fill();
      const fl = Math.sin(time * 4 + p.seed * 9) * 2;
      glow(ctx, x, y - 24 * s, 46 * s, '#ff9a48', .22);
      poly(ctx, [[x - 6 * s, y - 17 * s], [x + fl, y - 36 * s], [x + 5 * s, y - 17 * s]], '#ffb04a', null);
      poly(ctx, [[x - 3 * s, y - 17 * s], [x + fl * .6, y - 29 * s], [x + 2 * s, y - 17 * s]], '#ffe6a0', null);
      break;
    }
    case 'chain': {
      ctx.strokeStyle = 'rgba(60,56,60,.8)'; ctx.lineWidth = 2;
      for (let i = 0; i < 8; i++) { ctx.beginPath(); ctx.ellipse(x + Math.sin(i) * 2, y - 110 * s + i * 13 * s, 3, 6, 0, 0, 6.3); ctx.stroke(); }
      break;
    }
    case 'skull_pile': {
      shadow(ctx, x, y + 1, 16 * s, 4 * s, .3);
      for (let i = 0; i < 4; i++) {
        ctx.fillStyle = i % 2 ? '#d8d0bc' : '#b8b09c';
        ctx.beginPath(); ctx.arc(x - 8 * s + i * 5 * s, y - 4 * s - (i % 2) * 4 * s, 4 * s, 0, 6.3); ctx.fill();
        ctx.fillStyle = '#2a2020'; ctx.beginPath(); ctx.arc(x - 9 * s + i * 5 * s, y - 5 * s - (i % 2) * 4 * s, 1.2, 0, 6.3); ctx.fill();
      }
      break;
    }
    case 'barrel': {
      shadow(ctx, x, y + 1, 10 * s, 3 * s, .25);
      ctx.fillStyle = '#6a4a32'; ctx.beginPath(); ctx.ellipse(x, y - 4 * s, 8 * s, 10 * s, 0, 0, 6.3); ctx.fill();
      ctx.strokeStyle = '#3a2a20'; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.ellipse(x, y - 4 * s, 8 * s, 10 * s, 0, 0, 6.3); ctx.stroke();
      ctx.strokeStyle = 'rgba(200,160,100,.4)'; ctx.beginPath(); ctx.moveTo(x - 7 * s, y - 9 * s); ctx.lineTo(x + 7 * s, y - 9 * s); ctx.moveTo(x - 8 * s, y - 1 * s); ctx.lineTo(x + 8 * s, y - 1 * s); ctx.stroke();
      break;
    }
    case 'lamp': {
      shadow(ctx, x, y + 1, 8 * s, 3 * s, .25);
      ctx.fillStyle = '#3a3028'; ctx.fillRect(x - 2 * s, y - 46 * s, 4 * s, 46 * s);
      ctx.fillStyle = '#2a2420'; ctx.fillRect(x - 5 * s, y - 5 * s, 10 * s, 5 * s);
      glow(ctx, x, y - 52 * s, 42 * s, '#ffd888', .22);
      ctx.fillStyle = '#ffe0a0'; ctx.beginPath(); ctx.arc(x, y - 52 * s, 5 * s, 0, 6.3); ctx.fill();
      ctx.strokeStyle = '#5a4a38'; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.moveTo(x, y - 58 * s); ctx.lineTo(x, y - 46 * s); ctx.stroke();
      break;
    }
    case 'fence': {
      ctx.strokeStyle = '#5a4432'; ctx.lineWidth = 2.4 * s;
      ctx.beginPath(); ctx.moveTo(x - 20 * s, y - 4 * s); ctx.lineTo(x - 20 * s, y - 20 * s); ctx.moveTo(x + 20 * s, y - 4 * s); ctx.lineTo(x + 20 * s, y - 20 * s); ctx.stroke();
      ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(x - 22 * s, y - 10 * s); ctx.lineTo(x + 22 * s, y - 10 * s); ctx.moveTo(x - 22 * s, y - 17 * s); ctx.lineTo(x + 22 * s, y - 17 * s); ctx.stroke();
      break;
    }
    case 'banner':
    case 'banner_dark': {
      const cloth = p.type === 'banner' ? '#a8443a' : '#3a3450';
      ctx.fillStyle = '#4a3a2a'; ctx.fillRect(x - 1, y - 80 * s, 2.5, 80 * s);
      const fl = Math.sin(time * 2 + p.seed * 4) * 3;
      poly(ctx, [[x + 1, y - 78 * s], [x + 26 * s + fl, y - 74 * s], [x + 24 * s + fl, y - 34 * s], [x + 12 * s + fl * .5, y - 38 * s], [x + 1, y - 34 * s]], cloth, 'rgba(20,16,20,.4)', 1);
      ctx.fillStyle = 'rgba(255,220,140,.5)'; ctx.beginPath(); ctx.arc(x + 13 * s + fl * .5, y - 56 * s, 4 * s, 0, 6.3); ctx.fill();
      break;
    }
    case 'standing_stone': {
      shadow(ctx, x, y + 1, 16 * s, 5 * s, .32);
      poly(ctx, [[x - 9 * s, y], [x - 11 * s, y - 38 * s], [x - 4 * s, y - 50 * s], [x + 6 * s, y - 46 * s], [x + 10 * s, y]], '#6e7a72', 'rgba(20,30,26,.7)', 1.4);
      ctx.strokeStyle = 'rgba(150,240,200,.6)'; ctx.lineWidth = 1.2;
      ctx.beginPath(); ctx.moveTo(x - 2 * s, y - 36 * s); ctx.lineTo(x + 4 * s, y - 28 * s); ctx.lineTo(x - 2 * s, y - 20 * s); ctx.lineTo(x + 3 * s, y - 12 * s); ctx.stroke();
      glow(ctx, x, y - 28 * s, 20 * s, '#9fe8c0', .1);
      break;
    }
    case 'ruin_altar': {
      shadow(ctx, x, y + 1, 20 * s, 6 * s, .3);
      ctx.fillStyle = '#7a7466'; ctx.fillRect(x - 17 * s, y - 16 * s, 34 * s, 16 * s);
      ctx.fillStyle = '#a09a8a'; ctx.fillRect(x - 19 * s, y - 20 * s, 38 * s, 6 * s);
      ctx.fillStyle = 'rgba(140,220,190,.4)';
      ctx.beginPath(); ctx.arc(x, y - 23 * s, 3 * s, 0, 6.3); ctx.fill();
      break;
    }
    case 'arch': {
      ctx.strokeStyle = '#8a8478'; ctx.lineWidth = 8 * s;
      ctx.beginPath(); ctx.arc(x, y - 26 * s, 26 * s, Math.PI, 0); ctx.stroke();
      ctx.fillStyle = '#8a8478'; ctx.fillRect(x - 30 * s, y - 28 * s, 9 * s, 28 * s); ctx.fillRect(x + 21 * s, y - 28 * s, 9 * s, 28 * s);
      ctx.strokeStyle = 'rgba(20,18,20,.4)'; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.arc(x, y - 26 * s, 26 * s, Math.PI, 0); ctx.stroke();
      break;
    }
    case 'well': {
      shadow(ctx, x, y + 1, 22 * s, 6 * s, .3);
      ctx.fillStyle = '#77705f'; ctx.beginPath(); ctx.ellipse(x, y, 20 * s, 9 * s, 0, 0, 6.3); ctx.fill();
      ctx.fillStyle = '#3a4e56'; ctx.beginPath(); ctx.ellipse(x, y - 3 * s, 15 * s, 6 * s, 0, 0, 6.3); ctx.fill();
      ctx.strokeStyle = '#8a8270'; ctx.lineWidth = 3 * s; ctx.beginPath(); ctx.ellipse(x, y, 20 * s, 9 * s, 0, 0, 6.3); ctx.stroke();
      if (p.lava) { glow(ctx, x, y - 3 * s, 34 * s, '#ff7a30', .16); }
      break;
    }
    case 'sign': {
      shadow(ctx, x, y + 1, 8 * s, 3 * s, .25);
      ctx.fillStyle = '#4a3324'; ctx.fillRect(x - 2 * s, y - 32 * s, 4 * s, 32 * s);
      ctx.fillStyle = '#8a6a44'; ctx.fillRect(x - 17 * s, y - 38 * s, 34 * s, 17 * s);
      ctx.strokeStyle = 'rgba(30,20,15,.5)'; ctx.lineWidth = 1; ctx.strokeRect(x - 17 * s, y - 38 * s, 34 * s, 17 * s);
      ctx.fillStyle = 'rgba(40,28,20,.7)'; ctx.fillRect(x - 12 * s, y - 33 * s, 18 * s, 1.5); ctx.fillRect(x - 12 * s, y - 29 * s, 22 * s, 1.5); ctx.fillRect(x - 12 * s, y - 25 * s, 13 * s, 1.5);
      break;
    }
    case 'pillar': {
      shadow(ctx, x, y + 1, 14 * s, 4 * s, .3);
      ctx.fillStyle = '#c8c2ae'; ctx.fillRect(x - 9 * s, y - 58 * s, 18 * s, 58 * s);
      ctx.fillStyle = 'rgba(255,255,255,.12)'; ctx.fillRect(x - 9 * s, y - 58 * s, 4 * s, 58 * s);
      ctx.fillStyle = '#b0aa96'; ctx.fillRect(x - 13 * s, y - 63 * s, 26 * s, 6 * s); ctx.fillRect(x - 13 * s, y - 6 * s, 26 * s, 6 * s);
      ctx.strokeStyle = 'rgba(230,210,150,.5)'; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(x, y - 50 * s); ctx.lineTo(x, y - 14 * s); ctx.stroke();
      break;
    }
    case 'floating_rune': {
      const fy = y - 52 * s + Math.sin(time * 1.3 + p.seed * 7) * 5;
      glow(ctx, x, fy, 26 * s, '#ffe8a0', .13);
      ctx.strokeStyle = 'rgba(255,230,160,.8)'; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.arc(x, fy, 10 * s, 0, 6.3); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(x - 6 * s, fy + 5 * s); ctx.lineTo(x + 6 * s, fy - 5 * s); ctx.moveTo(x + 5 * s, fy + 6 * s); ctx.lineTo(x - 3 * s, fy - 3 * s); ctx.stroke();
      break;
    }
    case 'celestial_pillar': {
      shadow(ctx, x, y + 1, 20 * s, 6 * s, .28);
      const g = ctx.createLinearGradient(x - 14 * s, y, x + 14 * s, y);
      g.addColorStop(0, '#b8b2a0'); g.addColorStop(.5, '#f0ead6'); g.addColorStop(1, '#a49e8c');
      ctx.fillStyle = g; ctx.fillRect(x - 13 * s, y - 90 * s, 26 * s, 90 * s);
      for (let i = 0; i < 5; i++) { ctx.fillStyle = 'rgba(80,76,66,.18)'; ctx.fillRect(x - 9 * s + i * 4.5 * s, y - 84 * s, 1.5, 78 * s); }
      ctx.fillStyle = '#e8e2cc'; ctx.fillRect(x - 18 * s, y - 98 * s, 36 * s, 8 * s);
      ctx.fillStyle = '#ffefb8'; ctx.beginPath(); ctx.arc(x, y - 102 * s, 4 * s, 0, 6.3); ctx.fill();
      glow(ctx, x, y - 102 * s, 30 * s, '#ffe8a0', .16);
      break;
    }
    case 'throne': {
      shadow(ctx, x, y + 1, 30 * s, 8 * s, .35);
      ctx.fillStyle = '#b8b29c'; ctx.fillRect(x - 22 * s, y - 48 * s, 44 * s, 48 * s);
      ctx.fillStyle = '#d8d2bc'; ctx.fillRect(x - 16 * s, y - 42 * s, 32 * s, 10 * s);
      poly(ctx, [[x - 22 * s, y - 48 * s], [x - 18 * s, y - 72 * s], [x + 18 * s, y - 72 * s], [x + 22 * s, y - 48 * s]], '#c8c2ac', 'rgba(30,28,26,.5)', 1);
      glow(ctx, x, y - 56 * s, 38 * s, '#ffe8a0', .14);
      break;
    }
    default: break;
  }
}

function drawAstrolabe(ctx, x, y, time) {
  glow(ctx, x, y - 30, 30, '#ffe8a0', .16);
  ctx.strokeStyle = 'rgba(255,235,170,.8)'; ctx.lineWidth = 1.5;
  ctx.save(); ctx.translate(x, y - 30); ctx.rotate(time * .4);
  ctx.beginPath(); ctx.arc(0, 0, 10, 0, 6.3); ctx.stroke();
  ctx.beginPath(); ctx.ellipse(0, 0, 4, 13, .3, 0, 6.3); ctx.stroke();
  ctx.restore();
}

export function drawEnvironment(ctx, region, cam, time) {
  // Draw all props and buildings in painter order, split into behind/front by y
  const items = [];
  for (const p of region.props) {
    if (p.x - cam.x < -180 || p.x - cam.x > cam.w + 180 || p.y - cam.y < -220 || p.y - cam.y > cam.h + 160) continue;
    items.push({ y: p.y, kind: 'prop', p });
  }
  for (const b of region.buildings) {
    if (b.x - cam.x < -b.w - 200 || b.x - cam.x > cam.w + 200 || b.y - cam.y < -b.h - 240 || b.y - cam.y > cam.h + 200) continue;
    items.push({ y: b.y + b.h, kind: 'building', b });
  }
  items.sort((a, b) => a.y - b.y);
  for (const it of items) {
    if (it.kind === 'prop') drawProp(ctx, it.p, cam, time, region);
    else drawBuilding(ctx, it.b, cam, time);
  }
  // fixed interactive objects
  for (const i of region.interactables) {
    const x = i.x - cam.x, y = i.y - cam.y;
    if (x < -100 || x > cam.w + 100 || y < -100 || y > cam.h + 100) continue;
    if (i.type === 'well') {
      // below entities; drawn here
      drawProp(ctx, { type: 'well', x: i.x, y: i.y, seed: .3, scale: 1, lava: i.lava }, cam, time, region);
    } else if (i.type === 'sign') {
      drawProp(ctx, { type: 'sign', x: i.x, y: i.y, seed: .4 }, cam, time, region);
    } else if (i.type === 'astrolabe') {
      drawAstrolabe(ctx, x, y, time);
    }
  }
}

export function drawShrines(ctx, region, cam, time) {
  for (const s of region.shrines) {
    const x = s.x - cam.x, y = s.y - cam.y;
    if (x < -100 || x > cam.w + 100 || y < -100 || y > cam.h + 100) continue;
    shadow(ctx, x, y + 4, 30, 8, .35);
    // stone circle
    ctx.fillStyle = '#6a665c';
    ctx.beginPath(); ctx.ellipse(x, y + 2, 28, 10, 0, 0, 6.3); ctx.fill();
    ctx.fillStyle = '#8a8478';
    ctx.beginPath(); ctx.ellipse(x, y, 22, 7, 0, 0, 6.3); ctx.fill();
    // floating crystal
    const fy = y - 34 + Math.sin(time * 1.4 + s.x * .01) * 4;
    glow(ctx, x, fy, 50, '#ffe6a0', .25);
    poly(ctx, [[x, fy - 20], [x - 8, fy], [x, fy + 18], [x + 8, fy]], 'rgba(255,240,190,.85)', 'rgba(255,255,255,.6)', 1.2);
    poly(ctx, [[x, fy - 20], [x - 8, fy], [x, fy + 4]], 'rgba(255,255,255,.6)', null);
    // motes
    for (let i = 0; i < 4; i++) {
      const a = time * .7 + i * 1.7 + s.x;
      ctx.fillStyle = `rgba(255,235,170,${.25 + Math.sin(a * 2) * .15})`;
      ctx.beginPath(); ctx.arc(x + Math.cos(a) * 22, y - 24 + Math.sin(a * 1.3) * 20, 1.3, 0, 6.3); ctx.fill();
    }
    // pillars
    ctx.fillStyle = '#8a8478'; ctx.fillRect(x - 26, y - 18, 5, 18); ctx.fillRect(x + 21, y - 18, 5, 18);
    ctx.fillStyle = '#c8c0aa'; ctx.fillRect(x - 28, y - 22, 9, 4); ctx.fillRect(x + 19, y - 22, 9, 4);
  }
}

export function drawStones(ctx, region, cam, time) {
  for (const i of region.interactables) {
    if (i.type !== 'stone') continue;
    const x = i.x - cam.x, y = i.y - cam.y;
    if (x < -120 || x > cam.w + 120 || y < -120 || y > cam.h + 120) continue;
    shadow(ctx, x, y + 2, 26, 8, .35);
    glow(ctx, x, y - 38, 55, i.glow || '#ffe6a0', i.active ? .3 : .12);
    poly(ctx, [[x - 18, y], [x - 20, y - 48], [x - 8, y - 72], [x + 12, y - 66], [x + 20, y - 14], [x + 16, y]], '#65716a', 'rgba(24,34,30,.8)', 1.4);
    poly(ctx, [[x - 18, y - 48], [x - 8, y - 72], [x + 2, y - 48], [x - 4, y - 18]], '#7c8880', null);
    ctx.strokeStyle = i.glow || '#ffe6a0'; ctx.lineWidth = 1.6;
    ctx.beginPath(); ctx.moveTo(x - 4, y - 60); ctx.lineTo(x + 6, y - 50); ctx.lineTo(x - 3, y - 40); ctx.lineTo(x + 5, y - 28); ctx.lineTo(x - 2, y - 18); ctx.stroke();
    for (let k = 0; k < 3; k++) {
      const a = time * .8 + k * 2;
      ctx.fillStyle = rgba(i.glow || '#ffe6a0', .3);
      ctx.beginPath(); ctx.arc(x + Math.cos(a) * 28, y - 42 + Math.sin(a * 1.2) * 24, 1.3, 0, 6.3); ctx.fill();
    }
  }
}

export function drawCampfire(ctx, x, y, time, color = '#ff9a48') {
  const fl = Math.sin(time * 5 + x) * 2;
  glow(ctx, x, y - 12, 50, color, .18);
  ctx.fillStyle = '#4a3020'; ctx.beginPath(); ctx.ellipse(x, y, 16, 5, 0, 0, 6.3); ctx.fill();
  poly(ctx, [[x - 9, y], [x + fl, y - 24], [x + 8, y]], color, null);
  poly(ctx, [[x - 4, y], [x + fl * .6, y - 16], [x + 4, y]], '#ffe6a0', null);
}

export { drawProp, drawBuilding, shadow, glow };

import { shadow, glow } from './props.js';
import { rgba, shade, clamp, lerp, easeOut } from '../core/utils.js';
import { CREATURES, CREATURE_TYPES } from '../data/creatures.js';

const OUT = 'rgba(20,16,24,.88)';

function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y); ctx.arcTo(x + w, y, x + w, y + h, rr); ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr); ctx.arcTo(x, y, x + w, y, rr); ctx.closePath();
}

function drawCape(ctx, look, facing, sway, s, color) {
  if (!color) return;
  const back = facing === 'up';
  const side = facing === 'left' || facing === 'right';
  const w = side ? 13 : 17;
  ctx.beginPath();
  ctx.moveTo(-w * s, -42 * s);
  ctx.quadraticCurveTo((-w - 5) * s, -18 * s, (-w - 4 + sway) * s, -2 * s);
  ctx.quadraticCurveTo(0, 4 * s, (w + 3 + sway) * s, -3 * s);
  ctx.quadraticCurveTo((w + 3) * s, -22 * s, w * s, -42 * s);
  ctx.closePath();
  const g = ctx.createLinearGradient(0, -42 * s, 0, 0);
  g.addColorStop(0, shade(color, .1)); g.addColorStop(1, shade(color, -.28));
  ctx.fillStyle = g; ctx.fill();
  ctx.strokeStyle = 'rgba(15,12,18,.55)'; ctx.lineWidth = 1.2; ctx.stroke();
  if (back) { ctx.fillStyle = 'rgba(255,255,255,.05)'; ctx.fillRect(-w * .6 * s, -40 * s, w * 1.2 * s, 34 * s); }
}

function drawLeg(ctx, x, y, w, h, color, boot, swing, s) {
  ctx.save(); ctx.translate(x, y); ctx.rotate(swing * .18);
  ctx.fillStyle = color;
  roundRect(ctx, -w / 2, 0, w, h, w * .45); ctx.fill();
  ctx.strokeStyle = 'rgba(20,16,22,.5)'; ctx.lineWidth = 1; ctx.stroke();
  ctx.fillStyle = boot;
  roundRect(ctx, -w / 2 - 1, h - 4, w + 3, 6, 2.5); ctx.fill();
  ctx.strokeStyle = 'rgba(15,12,16,.6)'; ctx.stroke();
  ctx.restore();
}

function drawArm(ctx, x, y, len, color, handColor, angle, s, sleeve = null) {
  ctx.save(); ctx.translate(x, y); ctx.rotate(angle);
  ctx.fillStyle = sleeve || color;
  roundRect(ctx, -3 * s, 0, 6 * s, len, 3 * s); ctx.fill();
  ctx.strokeStyle = 'rgba(20,16,22,.5)'; ctx.lineWidth = 1; ctx.stroke();
  ctx.fillStyle = handColor;
  ctx.beginPath(); ctx.arc(0, len, 3.2 * s, 0, 6.3); ctx.fill();
  ctx.restore();
}

function drawWeapon(ctx, handX, handY, angle, type, s, glowColor, time, active = false) {
  ctx.save(); ctx.translate(handX, handY); ctx.rotate(angle);
  const scale = type === 'greatsword' ? 1.25 : type === 'daggers' ? .72 : type === 'staff' ? 1.15 : 1;
  // hilt
  ctx.fillStyle = '#7a5a34';
  ctx.fillRect(-2 * s, -3 * s, 4 * s, 9 * s);
  ctx.fillStyle = '#c8a060';
  ctx.fillRect(-6 * s, 4 * s, 12 * s, 2.4 * s);
  ctx.fillStyle = '#5a3e26';
  ctx.beginPath(); ctx.arc(0, 7.5 * s, 2.2 * s, 0, 6.3); ctx.fill();
  if (type === 'staff') {
    ctx.strokeStyle = '#6a4a32'; ctx.lineWidth = 2.4 * s;
    ctx.beginPath(); ctx.moveTo(0, -2 * s); ctx.lineTo(0, -52 * s); ctx.stroke();
    ctx.strokeStyle = '#c8a060'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(0, -52 * s, 4 * s, 0, 6.3); ctx.stroke();
    glow(ctx, 0, -52 * s, 14 * s, glowColor, .4);
    ctx.fillStyle = '#fff2c0'; ctx.beginPath(); ctx.arc(0, -52 * s, 2 * s, 0, 6.3); ctx.fill();
    ctx.restore(); return;
  }
  // blade
  const len = (type === 'greatsword' ? 38 : type === 'daggers' ? 16 : 30) * s * scale;
  const wid = type === 'greatsword' ? 4.2 : type === 'daggers' ? 2.1 : 2.8;
  const g = ctx.createLinearGradient(-wid * s, 0, wid * s, 0);
  g.addColorStop(0, '#dfe6ef'); g.addColorStop(.45, '#fffbea'); g.addColorStop(1, '#9aa8b8');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(-wid * s, -2 * s);
  ctx.lineTo(-wid * .7 * s, -len + 4 * s);
  ctx.lineTo(0, -len);
  ctx.lineTo(wid * .7 * s, -len + 4 * s);
  ctx.lineTo(wid * s, -2 * s);
  ctx.closePath(); ctx.fill();
  ctx.strokeStyle = 'rgba(40,44,58,.6)'; ctx.lineWidth = .8; ctx.stroke();
  ctx.strokeStyle = 'rgba(255,255,255,.7)'; ctx.lineWidth = .7;
  ctx.beginPath(); ctx.moveTo(-wid * .25 * s, -3 * s); ctx.lineTo(-wid * .18 * s, -len + 6 * s); ctx.stroke();
  if (active || type === 'celestial') {
    ctx.globalCompositeOperation = 'lighter';
    glow(ctx, 0, -len * .55, len * 1.4, glowColor, type === 'celestial' ? .3 : .16);
    ctx.globalCompositeOperation = 'source-over';
  }
  if (type === 'daggers') {
    // second dagger
    ctx.rotate(-.3);
    ctx.fillStyle = '#dfe6ef';
    ctx.beginPath(); ctx.moveTo(3 * s, 0); ctx.lineTo(4 * s, -14 * s); ctx.lineTo(5 * s, 0); ctx.closePath(); ctx.fill();
  }
  ctx.restore();
}

export function drawHumanoid(ctx, x, y, opts = {}) {
  const look = opts.look || {};
  const s = (opts.scale || 1) * (look.height || 1);
  const facing = opts.facing || 'down';
  const side = facing === 'left' || facing === 'right';
  const back = facing === 'up';
  const flip = facing === 'left';
  const time = opts.time || 0;
  const moving = !!opts.moving;
  const phase = opts.phase || 0;
  const walk = moving ? Math.sin(phase * 10) : 0;
  const bob = moving ? Math.abs(Math.sin(phase * 10)) * 1.2 : Math.sin(time * 1.7 + (opts.seed || 0) * 5) * .7;
  const attack = opts.attack;
  const atkP = attack ? clamp(attack.progress || 0) : 0;
  const attackActive = attack && attack.active;
  const dodge = opts.dodge || 0;
  const block = opts.block;
  const hurt = opts.hurt || 0;

  shadow(ctx, x, y + 1, 15 * s, 5 * s, .34);
  if (hurt > .05) glow(ctx, x, y - 26 * s, 34 * s, '#ff5050', hurt * .18);

  ctx.save();
  ctx.translate(x, y - bob * s);
  if (flip) ctx.scale(-1, 1);
  if (dodge > 0) { ctx.rotate(-.16 * flip * dodge); ctx.translate(0, -2 * s); }

  const outfit = look.outfit || '#445a80';
  const accent = look.accent || '#c8a060';
  const skin = look.skin || '#e8bd96';
  const hair = look.hair || '#3a2a24';
  const boot = shade(outfit, -.35);
  const armorLook = look.armor !== undefined ? look.armor : (look.armorLook || 0);
  const capeColor = look.capeColor || (look.accessory === 1 ? accent : null);

  // Cape behind
  if (capeColor) drawCape(ctx, look, facing, Math.sin(time * 2.2 + phase) * (moving ? 2.4 : .8), s, capeColor);

  // legs
  const legY = -20 * s, legH = 20 * s, legW = 5.4 * s;
  drawLeg(ctx, -4.4 * s, legY, legW, legH, shade(outfit, -.18), boot, walk, s);
  drawLeg(ctx, 4.4 * s, legY, legW, legH, shade(outfit, -.08), boot, -walk, s);

  // back arm
  const handColor = skin;
  const sleeve = armorLook > 0 ? shade(outfit, .12) : outfit;
  if (!side) drawArm(ctx, -9 * s, -37 * s, 15 * s, sleeve, handColor, .18 + walk * .05, s);

  // torso
  const torsoG = ctx.createLinearGradient(-9 * s, -42 * s, 9 * s, -20 * s);
  torsoG.addColorStop(0, shade(outfit, .14)); torsoG.addColorStop(.55, outfit); torsoG.addColorStop(1, shade(outfit, -.22));
  ctx.beginPath();
  ctx.moveTo(-9 * s, -41 * s);
  ctx.quadraticCurveTo(-11 * s, -30 * s, -7 * s, -19 * s);
  ctx.lineTo(7 * s, -19 * s);
  ctx.quadraticCurveTo(11 * s, -30 * s, 9 * s, -41 * s);
  ctx.quadraticCurveTo(0, -45 * s, -9 * s, -41 * s);
  ctx.closePath();
  ctx.fillStyle = torsoG; ctx.fill();
  ctx.strokeStyle = OUT; ctx.lineWidth = 1.3; ctx.stroke();
  // belt
  ctx.fillStyle = shade(accent, -.15); ctx.fillRect(-8 * s, -23 * s, 16 * s, 3.4 * s);
  ctx.fillStyle = '#e8c878'; ctx.fillRect(-2 * s, -23.4 * s, 4 * s, 3.8 * s);
  // armor
  if (armorLook > 0) {
    const plate = armorLook === 2 ? '#e8e2cc' : '#b8c0c8';
    ctx.fillStyle = plate;
    ctx.beginPath();
    ctx.moveTo(-8 * s, -39 * s); ctx.lineTo(8 * s, -39 * s); ctx.lineTo(6 * s, -26 * s); ctx.lineTo(0, -22 * s); ctx.lineTo(-6 * s, -26 * s); ctx.closePath();
    ctx.fill(); ctx.strokeStyle = 'rgba(50,48,52,.5)'; ctx.lineWidth = 1; ctx.stroke();
    // pauldrons
    ctx.fillStyle = shade(plate, -.08);
    ctx.beginPath(); ctx.ellipse(-9 * s, -40 * s, 5.4 * s, 4 * s, -.3, 0, 6.3); ctx.fill();
    ctx.beginPath(); ctx.ellipse(9 * s, -40 * s, 5.4 * s, 4 * s, .3, 0, 6.3); ctx.fill();
    ctx.strokeStyle = 'rgba(30,28,32,.4)'; ctx.stroke();
    if (armorLook === 2) {
      ctx.strokeStyle = 'rgba(255,230,160,.7)'; ctx.lineWidth = .9;
      ctx.beginPath(); ctx.moveTo(0, -36 * s); ctx.lineTo(0, -26 * s); ctx.moveTo(-4 * s, -33 * s); ctx.lineTo(4 * s, -33 * s); ctx.stroke();
    }
  } else {
    // leather straps
    ctx.strokeStyle = 'rgba(60,40,28,.65)'; ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.moveTo(-7 * s, -39 * s); ctx.lineTo(4 * s, -25 * s); ctx.stroke();
  }
  // scarf / collar
  if (look.accessory === 2 || look.scarf) {
    ctx.fillStyle = accent;
    roundRect(ctx, -8 * s, -44 * s, 16 * s, 4 * s, 2 * s); ctx.fill();
    const sw = Math.sin(time * 3 + phase) * 2;
    ctx.beginPath(); ctx.moveTo(3 * s, -42 * s); ctx.quadraticCurveTo(12 * s, -40 * s + sw, 14 * s, -30 * s + sw); ctx.quadraticCurveTo(9 * s, -36 * s, 3 * s, -38 * s); ctx.fill();
  }

  // head
  const headY = -49 * s;
  // hair back
  if (look.hairStyle === 0 || look.hairStyle === 2) {
    ctx.fillStyle = shade(hair, -.18);
    ctx.beginPath(); ctx.ellipse(0, headY + 5 * s, 9.4 * s, 11 * s, 0, 0, 6.3); ctx.fill();
    if (look.hairStyle === 2) {
      ctx.strokeStyle = shade(hair, -.05); ctx.lineWidth = 4 * s; ctx.lineCap = 'round';
      const sway = Math.sin(time * 1.8) * 1.4;
      ctx.beginPath(); ctx.moveTo(6 * s, headY + 4 * s); ctx.quadraticCurveTo(13 * s + sway, headY + 14 * s, 9 * s + sway, headY + 24 * s); ctx.stroke();
    }
  }
  // neck
  ctx.fillStyle = shade(skin, -.12); ctx.fillRect(-3 * s, -44 * s, 6 * s, 4 * s);
  // face
  ctx.fillStyle = skin;
  ctx.beginPath(); ctx.ellipse(0, headY, 8.2 * s, 8.6 * s, 0, 0, 6.3); ctx.fill();
  ctx.strokeStyle = 'rgba(60,35,30,.55)'; ctx.lineWidth = .9; ctx.stroke();
  // ears
  if (!back) { ctx.fillStyle = shade(skin, -.04); ctx.beginPath(); ctx.arc(-8 * s, headY + 1 * s, 2 * s, 0, 6.3); ctx.arc(8 * s, headY + 1 * s, 2 * s, 0, 6.3); ctx.fill(); }
  // hair top
  ctx.fillStyle = hair;
  if (look.hairStyle === 3) {
    ctx.beginPath(); ctx.ellipse(0, headY - 3 * s, 8.4 * s, 6.2 * s, 0, Math.PI, 0); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.08)'; ctx.beginPath(); ctx.ellipse(-2 * s, headY - 4 * s, 4 * s, 2 * s, -.3, 0, 6.3); ctx.fill();
  } else if (look.hairStyle === 1) {
    ctx.beginPath();
    ctx.moveTo(-9 * s, headY - 1 * s);
    ctx.quadraticCurveTo(-8 * s, headY - 11 * s, 0, headY - 10 * s);
    ctx.quadraticCurveTo(9 * s, headY - 11 * s, 9 * s, headY - 1 * s);
    ctx.lineTo(7 * s, headY - 4 * s); ctx.lineTo(4 * s, headY - 2 * s); ctx.lineTo(2 * s, headY - 6 * s);
    ctx.lineTo(-1 * s, headY - 2 * s); ctx.lineTo(-4 * s, headY - 5 * s); ctx.lineTo(-6 * s, headY - 1 * s); ctx.closePath(); ctx.fill();
  } else {
    ctx.beginPath();
    ctx.moveTo(-9.2 * s, headY - 1 * s);
    ctx.quadraticCurveTo(-10 * s, headY - 12 * s, 0, headY - 11 * s);
    ctx.quadraticCurveTo(10 * s, headY - 12 * s, 9.2 * s, headY - 1 * s);
    ctx.quadraticCurveTo(8 * s, headY - 6 * s, 5 * s, headY - 5 * s);
    ctx.quadraticCurveTo(3 * s, headY - 9 * s, 0, headY - 6 * s);
    ctx.quadraticCurveTo(-3 * s, headY - 9 * s, -5 * s, headY - 5 * s);
    ctx.quadraticCurveTo(-8 * s, headY - 6 * s, -9.2 * s, headY - 1 * s);
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.12)';
    ctx.beginPath(); ctx.ellipse(-2 * s, headY - 7 * s, 4 * s, 1.8 * s, -.2, 0, 6.3); ctx.fill();
  }
  // face details
  if (!back) {
    if (side) {
      ctx.fillStyle = '#2a2024'; ctx.beginPath(); ctx.ellipse(3.6 * s, headY + .4 * s, 1.1 * s, 1.5 * s, 0, 0, 6.3); ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,.75)'; ctx.beginPath(); ctx.arc(3.9 * s, headY + .1 * s, .4 * s, 0, 6.3); ctx.fill();
      ctx.strokeStyle = 'rgba(120,60,50,.45)'; ctx.lineWidth = .7;
      ctx.beginPath(); ctx.moveTo(4.5 * s, headY + 4.4 * s); ctx.lineTo(6 * s, headY + 4.8 * s); ctx.stroke();
    } else {
      ctx.fillStyle = '#2a2024';
      ctx.beginPath(); ctx.ellipse(-3.3 * s, headY + .8 * s, 1.2 * s, 1.7 * s, 0, 0, 6.3); ctx.ellipse(3.3 * s, headY + .8 * s, 1.2 * s, 1.7 * s, 0, 0, 6.3); ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,.8)';
      ctx.beginPath(); ctx.arc(-3 * s, headY + .2 * s, .45 * s, 0, 6.3); ctx.arc(3.6 * s, headY + .2 * s, .45 * s, 0, 6.3); ctx.fill();
      ctx.strokeStyle = 'rgba(130,70,55,.5)'; ctx.lineWidth = .7;
      ctx.beginPath(); ctx.moveTo(-1.6 * s, headY + 4.6 * s); ctx.quadraticCurveTo(0, headY + 5.4 * s, 1.6 * s, headY + 4.6 * s); ctx.stroke();
      if (look.scar) { ctx.strokeStyle = 'rgba(150,70,60,.55)'; ctx.beginPath(); ctx.moveTo(4.2 * s, headY - 3.6 * s); ctx.lineTo(5.8 * s, headY + 2.6 * s); ctx.stroke(); }
    }
  }
  // beard
  if (look.beard) {
    ctx.fillStyle = shade(hair, .1);
    ctx.beginPath(); ctx.moveTo(-6 * s, headY + 4 * s); ctx.quadraticCurveTo(0, headY + 15 * s, 6 * s, headY + 4 * s); ctx.quadraticCurveTo(0, headY + 8 * s, -6 * s, headY + 4 * s); ctx.fill();
  }
  // helmet
  const showHelm = look.helmet || look.helmLook === 1 || look.helmLook === 2;
  if (showHelm || look.accessory === 3) {
    const metal = look.helmLook === 2 ? '#e0dac4' : '#9aa6b0';
    ctx.fillStyle = metal;
    ctx.beginPath(); ctx.ellipse(0, headY - 2.5 * s, 9.4 * s, 7.4 * s, 0, Math.PI, 0); ctx.fill();
    ctx.fillStyle = shade(metal, -.15); ctx.fillRect(-9.4 * s, headY - 3 * s, 18.8 * s, 3 * s);
    ctx.fillStyle = 'rgba(255,255,255,.3)'; ctx.beginPath(); ctx.ellipse(-2 * s, headY - 6 * s, 4 * s, 1.5 * s, -.2, 0, 6.3); ctx.fill();
    if (look.helmLook === 2) {
      ctx.strokeStyle = '#e8c878'; ctx.lineWidth = .8; ctx.beginPath(); ctx.moveTo(0, headY - 10 * s); ctx.lineTo(0, headY - 4 * s); ctx.stroke();
    }
    ctx.fillStyle = shade(skin, -.1); ctx.fillRect(-6 * s, headY - 1 * s, 12 * s, 2 * s);
  }

  // front arm and weapon
  const handY = -36 * s;
  const handX = side ? 8 * s : 9 * s;
  let armAngle = .4 + walk * .05;
  let weaponAngle = .8;
  if (block) { armAngle = 1.25; weaponAngle = -.35; }
  if (attack) {
    if (atkP < .28) { armAngle = -1.65; weaponAngle = -2.1; }
    else { const p = (atkP - .28) / .5; armAngle = lerp(-1.0, 1.5, easeOut(clamp(p))); weaponAngle = lerp(-1.7, 1.25, easeOut(clamp(p))); }
  }
  drawArm(ctx, handX, handY, 14 * s, sleeve, handColor, armAngle, s);
  const hx = handX + Math.sin(armAngle) * 14 * s;
  const hy = handY + Math.cos(armAngle) * 14 * s;
  if (opts.weapon !== false && look.weapon !== false) {
    drawWeapon(ctx, hx, hy, weaponAngle, opts.weapon || look.weapon || 'sword', s, look.weaponGlow || '#ffe8a0', time, !!opts.weaponGlow);
  }
  // block shield arc
  if (block) {
    ctx.strokeStyle = 'rgba(160,210,255,.7)'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(0, -30 * s, 18 * s, -1.2, 1.2); ctx.stroke();
  }
  ctx.restore();
}

export const HERO_LOOK_DEFAULT = { skin: '#e8bd96', hair: '#2b2733', hairStyle: 0, outfit: '#445a80', accent: '#c8a060', accessory: 1, armorLook: 0, face: 0 };

export function drawPlayer(ctx, player, camera, time) {
  const s = player.spriteScale || 1;
  drawHumanoid(ctx, player.x - camera.x, player.y - camera.y, {
    look: player.look, facing: player.facing, moving: player.moving, phase: player.walkPhase,
    time, attack: player.attackState, dodge: player.dodgeTimer > 0 ? 1 : 0,
    block: player.blocking, hurt: player.hurtFlash, scale: s, weapon: player.weaponType,
    weaponGlow: player.weaponType === 'celestial',
    seed: 0
  });
  // celestial aura
  if (player.weaponType === 'celestial') {
    ctx.save(); ctx.globalCompositeOperation = 'lighter';
    glow(ctx, player.x - camera.x, player.y - camera.y - 30, 42, '#ffe8a0', .08);
    ctx.restore();
  }
}

export function drawNPC(ctx, npc, camera, time) {
  const x = npc.x - camera.x, y = npc.y - camera.y;
  if (npc.hidden) return;
  drawHumanoid(ctx, x, y, {
    look: npc.visual, facing: npc.facing || 'down', moving: false, phase: 0, time: time + (npc.id.length * .7),
    scale: 1, weapon: npc.id === 'borin' || npc.id === 'ren' || npc.id === 'rhea' || npc.id === 'kael_camp' || npc.id === 'ash',
    seed: npc.x * .01
  });
  if (npc.visual?.glow) { ctx.save(); ctx.globalCompositeOperation = 'lighter'; glow(ctx, x, y - 30, 40, '#c8d8ff', .1); ctx.restore(); }
  // exclamation / marker
  if (npc.marker) {
    const bob = Math.sin(time * 3 + npc.x) * 3;
    ctx.fillStyle = '#ffe6a0'; ctx.font = 'bold 18px Georgia'; ctx.textAlign = 'center';
    ctx.shadowColor = '#000'; ctx.shadowBlur = 6;
    ctx.fillText('!', x, y - 68 + bob);
    ctx.shadowBlur = 0;
  }
}

function wolf(ctx, x, y, e, time) {
  const s = e.scale || 1;
  const dir = e.facing === 'left' ? -1 : 1;
  const run = Math.sin(time * 11 + e.seed * 8);
  const bob = Math.abs(run) * 2;
  ctx.save(); ctx.translate(x, y - bob); ctx.scale(dir, 1);
  shadow(ctx, 0, bob + 1, 22 * s, 6 * s, .32);
  // tail
  ctx.strokeStyle = '#3a333c'; ctx.lineWidth = 4 * s; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(-16 * s, -24 * s); ctx.quadraticCurveTo(-30 * s, -30 * s + run * 4, -34 * s, -16 * s); ctx.stroke();
  // legs
  ctx.strokeStyle = '#2e2933'; ctx.lineWidth = 3.4 * s;
  for (const [lx, ph] of [[-12, run], [-7, -run], [8, -run], [13, run]]) {
    ctx.beginPath(); ctx.moveTo(lx * s, -14 * s); ctx.lineTo(lx * s + ph * 3 * s, 0); ctx.stroke();
  }
  // body
  ctx.fillStyle = e.palette?.[0] || '#5d5660';
  ctx.beginPath(); ctx.ellipse(0, -22 * s, 18 * s, 10 * s, -.05, 0, 6.3); ctx.fill();
  ctx.strokeStyle = OUT; ctx.lineWidth = 1.2; ctx.stroke();
  // fur spikes
