  ctx.beginPath(); ctx.ellipse(17 * s, -28 * s, 10 * s, 8.5 * s, .2, 0, 6.3); ctx.fill();
  ctx.fillStyle = e.palette?.[0] || '#5d5660';
  ctx.beginPath(); ctx.moveTo(21 * s, -32 * s); ctx.lineTo(33 * s, -28 * s); ctx.lineTo(22 * s, -22 * s); ctx.closePath(); ctx.fill();
