202: function hasQ(g, id) { return g.questState(id)?.status === 'active'; }
203: function doneQ(g, id) { return g.questState(id)?.status === 'done'; }
204: function stepIs(g, id, idx) { const q = g.questState(id); return q?.status === 'active' && q.step === idx; }
