206: export function dialogueFor(npcId, g) {
207:   const f = g.flags;
208:   switch (npcId) {
209:     case 'nara': return naraDialogue(g);
210:     case 'borin': return borinDialogue(g);
211:     case 'elara': return elaraDialogue(g);
212:     case 'tomo': return tomoDialogue(g);
213:     case 'sibil': return sibilDialogue(g);
214:     case 'ren': return {
215:       start: [
216:         p('ren', 'La aldea sigue en pie gracias a ti. El bosque, en cambio, lleva años esperando a alguien que se atreva a escucharlo.'),
217:         p('ren', 'Si vas hacia el este, cruza el puente y no te acerques a las ruinas de noche. Las columnas cambian de sitio. O eso dice el vino.'),
218:         p('ren', 'Cuando el cielo se abrió, vi una espada de luz dentro de la grieta. Duró un latido. Luego la Gema volvió a apagarse.')
219:       ],
220:       repeat: [
221:         p('ren', 'La guardia no descansa. Bueno, yo sí. Pero no se lo digas a la capitana.')
222:       ]
223:     };
224:     case 'mira': return {
225:       start: [
226:         p('mira', 'Pan caliente, recién salido del horno. No hay mejor arma contra el miedo, criatura.'),
227:         p('mira', 'Dicen que la Gema se rompió porque alguien intentó cantar con la voz de otro. Yo solo sé que el pan se hace mejor en silencio.'),
228:         { choices: [
229:           { text: 'Comprar pan de viaje (15 de oro)', action: 'buy:pan_viaje:15', next: [] },
230:           { text: 'Despedirte', next: [] }
231:         ] }
232:       ],
233:       repeat: [
234:         p('mira', 'El horno nunca duerme. Yo tampoco, por desgracia.'),
235:         { choices: [
236:           { text: 'Comprar pan de viaje (15 de oro)', action: 'buy:pan_viaje:15', next: [] },
237:           { text: 'Despedirte', next: [] }
238:         ] }
239:       ]
240:     };
241:     case 'lyra': return lyraDialogue(g);
242:     case 'rhea': return rheaDialogue(g);
243:     case 'ash': return {
244:       start: [
245:         p('ash', 'No toques el metal con las manos desnudas. Aquí todo está caliente, incluso los recuerdos.'),
246:         { choices: [
247:           { text: 'Abrir la tienda de Ash', action: 'shop:ash', next: [] },
248:           { text: 'Despedirte', next: [] }
249:         ] }
250:       ]
251:     };
252:     case 'veyra': return veyraDialogue(g);
253:     case 'sel': return selDialogue(g);
254:     case 'kael_camp': return kaelCampDialogue(g);
255:     default: return { start: [p('ren', 'Que la luz de Lumen te acompañe.')] };
256:   }
257: }
