259: function naraDialogue(g) {
260:   if (doneQ(g, 'm6')) return { start: [p('nara', 'El mundo sigue cantando. Y esta vez, la canción incluye tu nombre.')] };
261:   if (hasQ(g, 'm3') && g.flags.kael_defeated) return { start: [
262:     p('nara', 'Kael no era el enemigo. Solo era el primero que se atrevió a mirar la grieta de cerca.'),
263:     hero('¿Qué hay al otro lado?'),
264:     p('nara', 'Drakmor. Ceniza sobre ceniza. Y una lágrima que lleva mil años esperando a que alguien la recoja.'),
265:     p('nara', 'La Profecía de Jugador Cero habla de ti. Del que no estaba escrito. Pero las profecías son como los mapas: solo muestran lo que el cartógrafo quiso ver.'),
266:     hero('No recuerdo quién soy.'),
267:     p('nara', 'Eso, precisamente, es lo que te hace libre. La Gema guarda la memoria del mundo. Si la recuperas... quizá también te recuperes a ti.'),
268:     { text: 'Nara dibuja un círculo en el aire. El Velo se abre, y del otro lado huele a hierro y a tormenta.', speaker: 'NARA', portrait: 'nara', role: 'Archivista de Lumen' },
269:     { choices: [
270:       { text: 'Cruzar hacia Drakmor', action: 'travel:drakmor:brasa', next: [] }
271:     ] }
272:   ] };
273:   if (hasQ(g, 'm2') && g.flags.guardian_defeated) return { start: [
274:     p('nara', 'Lo has conseguido. El fragmento de la Gema... está cantando.'),
275:     hero('La grieta del cielo se ha ensanchado.'),
276:     p('nara', 'La Convergencia ha comenzado. El Velo pierde notas, y lo que hay al otro lado empieza a escucharse.'),
277:     p('nara', 'Ve a la plaza. Hay algo que debes ver con tus propios ojos.'),
278:     { action: 'startQuest:m3', next: [] }
279:   ] };
280:   if (hasQ(g, 'm2')) return { start: [
281:     p('nara', 'Las tres piedras están en el bosque: al noroeste, junto al río y al sur. El Guardián despertará cuando las tres canten.'),
282:     p('nara', 'Si el Guardián te ataca, no huyas. Los espíritus respetan a quien mantiene la mirada.'),
283:     hero('¿Y si no soy ese Jugador Cero?'),
284:     p('nara', 'Entonces el mundo se equivocó al elegirte. No sería la primera vez que se equivoca.')
285:   ] };
286:   if (hasQ(g, 'm1') && g.flags.lobos_cleared) return { start: [
287:     p('nara', 'Has oído el pulso de la Gema, ¿verdad? No estás loco. La Gema se rompió, pero no se apagó.'),
288:     p('nara', 'Borin te espera en su herrería, al este de la plaza. Tiene algo que darte y muy poco tiempo para explicarlo.'),
289:     { action: 'advance:m1', next: [] }
290:   ] };
291:   if (hasQ(g, 'm1')) return { start: [
292:     p('nara', 'Te llamas Aurel. Eso dice la piedra del santuario. Aunque no sé si es tu nombre o el nombre que el mundo necesitaba.'),
293:     p('nara', 'Los lobos de ceniza han bajado del bosque. No son criaturas corruptas: están asustadas. Y el miedo muerde.'),
294:     hero('¿Qué quieres que haga?'),
295:     p('nara', 'Defiende la aldea. Tres lobos bastarán para que la manada retroceda. Después habla con Borin.'),
296:     { action: 'setFlag:lobos_quest', next: [] }
297:   ] };
298:   return { start: [
299:     p('nara', 'El que no estaba escrito... por fin abres los ojos.'),
300:     hero('¿Quién eres? ¿Dónde estoy?'),
301:     p('nara', 'Estás en Valdoria, aldea de Lumen. Yo soy Nara, y guardo libros que nadie lee. Tú eres Jugador Cero.'),
302:     p('nara', 'La Gema Celestial se rompió hace mil años. Desde entonces el Velo nos protege del silencio que hay afuera. Y desde hace tres noches, el Velo está... desafinando.'),
303:     { choices: [
304:       { text: '¿Qué es el Velo?', next: [p('nara', 'La membrana entre el mundo que conoces y la Primera Brasa. Una canción que nos mantiene completos. Si se rompe, no moriremos: nos convertiremos en ecos.')] },
305:       { text: '¿Por qué yo?', next: [p('nara', 'Porque la Gema te reconoció. No sé cómo ni por qué. Y esa, Aurel, es la primera cosa honesta que digo en años.')] }
306:     ] },
307:     p('nara', 'Los lobos de ceniza atacan la aldea. Necesito que empuñes esa espada oxidada y demuestres que la Gema no se equivocó.'),
308:     { action: 'startQuest:m1', next: [] }
309:   ] };
310: }
