312: function borinDialogue(g) {
313:   if (hasQ(g, 's_martillo') && g.flags.martillo_recogido) return { start: [
314:     p('borin', 'Mi martillo. Pensé que las ruinas se lo habrían tragado.'),
315:     hero('Estaba bajo una columna. Seguía caliente.'),
316:     p('borin', 'Claro que lo estaba. Lo forjé con la última brasa de mi padre. Toma esta hoja. La hice para ti mientras soñaba que volvías.'),
317:     { action: 'completeQuest:s_martillo', next: [
318:       p('borin', 'No le des las gracias a un viejo. Dale las gracias al acero, que aguanta más que nosotros.')
319:     ] }
320:   ] };
321:   if (hasQ(g, 'm1') && g.flags.lobos_cleared) return { start: [
322:     p('borin', 'Así que eres tú. Hueles a tormenta y a camino viejo.'),
323:     p('borin', 'La Gema no elige a cualquiera. O eso decía mi madre. También decía que las cabras hablan, así que tómelo con calma.'),
324:     p('borin', 'Toma. Un filo de Lumen. No es la Espada Celestial, pero corta lo que toca.'),
325:     { action: 'advance:m1', next: [
326:       p('borin', 'Las tres Piedras de Resonancia están en el bosque. Ve y despiértalas. Yo cuidaré de la aldea.'),
327:       { action: 'startQuest:m2', next: [] }
328:     ] }
329:   ] };
330:   if (hasQ(g, 'm1')) return { start: [
331:     p('borin', 'Aún no. Primero ayuda a Nara con esos lobos. No quiero darle una espada a alguien que no sabe sostenerla.')
332:   ] };
333:   if (!doneQ(g, 's_martillo') && (doneQ(g, 'm1') || hasQ(g, 'm2') || hasQ(g, 'm3'))) {
334:     if (hasQ(g, 's_martillo')) return { start: [
335:       p('borin', 'El martillo está en las Ruinas del Este, cruzando el río. Busca una columna partida junto al altar.'),
336:       p('borin', 'Y no te fíes de las estatuas. Algunas tienen muy mal carácter.')
337:     ] };
338:     return { start: [
339:       p('borin', 'Tengo un problema de juventud. Dejé mi martillo en las Ruinas del Este cuando era un idiota con prisa.'),
340:       p('borin', 'Si lo recuperas, te daré algo que hice con estas manos. Algo que corta.'),
341:       { choices: [
342:         { text: 'Aceptar la misión', action: 'startQuest:s_martillo', next: [p('borin', 'Busca la columna partida junto al altar. Y vuelve entero.')] },
343:         { text: 'Quizá más tarde', next: [] }
344:       ] }
345:     ] };
346:   }
347:   return {
348:     start: [
349:       p('borin', 'El acero no miente. La gente sí. Por eso prefiero el acero.'),
