45:   if (!l2) return Math.hypot(px - x1, py - y1);
46:   let t = ((px - x1) * dx + (py - y1) * dy) / l2;
47:   t = Math.max(0, Math.min(1, t));
48:   return Math.hypot(px - (x1 + t * dx), py - (y1 + t * dy));
49: }
