51: class RegionBuilder {
52:   constructor(meta) {
53:     this.meta = meta;
54:     this.w = meta.width; this.h = meta.height;
55:     this.tiles = new Uint8Array(this.w * this.h);
56:     this.solid = new Uint8Array(this.w * this.h);
57:     this.pathMask = new Uint8Array(this.w * this.h);
58:     this.propMask = new Uint8Array(this.w * this.h);
59:     this.rng = seededRandom(meta.seed);
60:     this.props = [];
61:     this.buildings = [];
62:     this.npcs = [];
63:     this.spawners = [];
64:     this.pickups = [];
65:     this.interactables = [];
66:     this.triggers = [];
67:     this.shrines = [];
68:     this.decor = [];
69:     this.clearings = [];
70:     this.tileDecor = [];
71:   }
72:   inBounds(x, y) { return x >= 0 && y >= 0 && x < this.w && y < this.h; }
73:   get(x, y) { return this.inBounds(x, y) ? this.tiles[idx(x, y, this.w)] : TERRAIN.CLIFF; }
74:   set(x, y, t, solid = null) {
75:     if (!this.inBounds(x, y)) return;
76:     this.tiles[idx(x, y, this.w)] = t;
77:     if (solid !== null) this.solid[idx(x, y, this.w)] = solid ? 1 : 0;
78:     else this.solid[idx(x, y, this.w)] = (t === TERRAIN.WATER || t === TERRAIN.LAVA || t === TERRAIN.CLIFF || t === TERRAIN.VOID) ? 1 : 0;
79:   }
80:   isSolidTile(x, y) { return this.inBounds(x, y) ? this.tiles[idx(x, y, this.w)] : TERRAIN.CLIFF; }
81:   isSolid(x, y) { return this.inBounds(x, y) ? this.solid[idx(x, y, this.w)] : 1; }
82:   addClearing(x, y, r) { this.clearings.push({ x, y, r }); }
83:   nearClearing(x, y, pad = 0) {
84:     for (const c of this.clearings) if (Math.hypot(x - c.x, y - c.y) < c.r + pad) return true;
85:     return false;
86:   }
87:   nearPath(x, y, pad = 2) {
88:     for (let yy = Math.floor(y - pad); yy <= y + pad; yy++) for (let xx = Math.floor(x - pad); xx <= x + pad; xx++) {
89:       if (this.inBounds(xx, yy) && this.pathMask[idx(xx, yy, this.w)]) return true;
90:     }
91:     return false;
92:   }
93:   carvePath(x1, y1, x2, y2, width = 2) {
94:     const steps = Math.ceil(Math.hypot(x2 - x1, y2 - y1) * 2);
95:     for (let i = 0; i <= steps; i++) {
96:       const t = i / steps;
97:       const cx = x1 + (x2 - x1) * t, cy = y1 + (y2 - y1) * t;
98:       for (let dy = -width; dy <= width; dy++) for (let dx = -width; dx <= width; dx++) {
99:         if (dx * dx + dy * dy > width * width + .4) continue;
100:         const x = Math.round(cx + dx), y = Math.round(cy + dy);
101:         if (!this.inBounds(x, y)) continue;
102:         const i2 = idx(x, y, this.w);
103:         this.pathMask[i2] = 1;
104:         const cur = this.tiles[i2];
105:         if (cur === TERRAIN.WATER) this.set(x, y, TERRAIN.BRIDGE, false);
106:         else if (cur === TERRAIN.LAVA) this.set(x, y, TERRAIN.BRIDGE, false);
107:         else if (cur !== TERRAIN.CLIFF && cur !== TERRAIN.VOID) this.set(x, y, TERRAIN.DIRT, false);
108:       }
109:     }
110:   }
111:   addProp(type, x, y, opts = {}) {
112:     const p = { type, x: x * TILE, y: y * TILE, tx: x, ty: y, seed: this.rng(), ...opts };
113:     this.props.push(p);
114:     if (opts.collide) {
115:       const r = opts.collide === true ? .5 : opts.collide;
116:       this.addCollider(x, y, r);
117:     }
118:     return p;
119:   }
120:   addCollider(tx, ty, r) {
121:     const key = `${Math.floor(tx)},${Math.floor(ty)}`;
122:     (this.colliderGrid ||= new Map());
123:     const arr = this.colliderGrid.get(key) || [];
124:     arr.push({ x: tx * TILE, y: ty * TILE, r: r * TILE });
125:     this.colliderGrid.set(key, arr);
126:   }
127:   addBuilding(b) {
128:     this.buildings.push({ ...b, x: b.x * TILE, y: b.y * TILE, w: b.w * TILE, h: b.h * TILE, tx: b.x, ty: b.y, tw: b.w, th: b.h });
129:     this.addClearing(b.x + b.w / 2, b.y + b.h / 2, Math.max(b.w, b.h) * .7);
130:     // block tiles under building, leave the front row walkable
131:     for (let yy = b.y; yy < b.y + b.h; yy++) for (let xx = b.x; xx < b.x + b.w; xx++) {
132:       if (this.inBounds(xx, yy)) { this.propMask[idx(xx, yy, this.w)] = 1; }
133:     }
134:     this.addCollider(b.x + b.w / 2, b.y + b.h * .55, 0);
135:     this.buildings[this.buildings.length - 1].collider = {
136:       x: b.x * TILE + TILE * .25, y: b.y * TILE + TILE * .42, w: b.w * TILE - TILE * .5, h: b.h * TILE - TILE * .2
137:     };
138:   }
139:   addNPC(id, x, y, opts = {}) {
140:     this.npcs.push({ id, x: x * TILE, y: y * TILE, anchorX: x * TILE, anchorY: y * TILE, facing: 'down', ...opts });
141:   }
142:   addSpawner(id, type, x, y, count = 3, radius = 5, respawn = 75) {
143:     this.spawners.push({ id, type, x: x * TILE, y: y * TILE, tx: x, ty: y, count, radius: radius * TILE, respawn });
144:   }
145:   addPickup(id, item, x, y, qty = 1, kind = 'item') {
146:     this.pickups.push({ id, item, x: x * TILE, y: y * TILE, qty, kind, bob: this.rng() * 6.28 });
147:   }
148:   addInteractable(type, x, y, data = {}) {
149:     this.interactables.push({ type, x: x * TILE, y: y * TILE, ...data });
150:   }
151:   addTrigger(id, x, y, r, data = {}) {
152:     this.triggers.push({ id, x: x * TILE, y: y * TILE, r: r * TILE, ...data });
153:   }
154:   addShrine(id, name, x, y, discovered = false) {
155:     const s = { id, name, x: x * TILE, y: y * TILE, discovered };
156:     this.shrines.push(s);
157:     this.addClearing(x, y, 4);
158:     return s;
159:   }
160: }
