494: function finalize(b, meta) {
495:   // Add building colliders to collider grid
496:   for (const bd of b.buildings) {
497:     if (!bd.collider) continue;
498:     const c = bd.collider;
499:     const tx = Math.floor((c.x + c.w / 2) / TILE), ty = Math.floor((c.y + c.h / 2) / TILE);
500:     const key = `${tx},${ty}`;
501:     const arr = b.colliderGrid.get(key) || [];
502:     arr.push({ x: c.x, y: c.y, r: 0, rect: { x: c.x, y: c.y, w: c.w, h: c.h } });
503:     b.colliderGrid.set(key, arr);
504:   }
505:   return {
506:     ...meta,
507:     tiles: b.tiles, solid: b.solid, pathMask: b.pathMask,
508:     props: b.props, buildings: b.buildings, npcs: b.npcs, spawners: b.spawners,
509:     pickups: b.pickups, interactables: b.interactables, triggers: b.triggers, shrines: b.shrines,
510:     colliderGrid: b.colliderGrid || new Map(),
511:     widthPx: b.w * TILE, heightPx: b.h * TILE,
512:     tileW: b.w, tileH: b.h
513:   };
514: }
