516: const cache = {};
517: export function getRegion(id) {
518:   if (!cache[id]) {
519:     if (id === 'valdoria') cache[id] = buildValdoria();
520:     else if (id === 'drakmor') cache[id] = buildDrakmor();
521:     else if (id === 'kansordore') cache[id] = buildKansordore();
522:     else throw new Error('Región desconocida: ' + id);
523:   }
524:   return cache[id];
525: }
