527: export function tileAt(region, px, py) {
528:   const x = Math.floor(px / TILE), y = Math.floor(py / TILE);
529:   if (x < 0 || y < 0 || x >= region.tileW || y >= region.tileH) return TERRAIN.CLIFF;
530:   return region.tiles[y * region.tileW + x];
531: }
532: 
533: export function tileSolidAt(region, px, py) {
534:   const x = Math.floor(px / TILE), y = Math.floor(py / TILE);
535:   if (x < 0 || y < 0 || x >= region.tileW || y >= region.tileH) return true;
536:   return !!region.solid[y * region.tileW + x];
537: }
538: 
539: export function collidersNear(region, x, y, r = 2) {
540:   const out = [];
541:   const cx = Math.floor(x / TILE), cy = Math.floor(y / TILE);
542:   for (let yy = cy - 2; yy <= cy + 2; yy++) for (let xx = cx - 2; xx <= cx + 2; xx++) {
543:     const arr = region.colliderGrid.get(`${xx},${yy}`);
544:     if (arr) out.push(...arr);
545:   }
546:   return out;
547: }
548: 
549: export function canStand(region, x, y, r = 13) {
550:   for (const [dx, dy] of [[-r, 0], [r, 0], [0, -r], [0, r], [0, 0]]) {
551:     if (tileSolidAt(region, x + dx, y + dy)) return false;
552:   }
553:   for (const c of collidersNear(region, x, y)) {
554:     if (c.rect) {
555:       const nx = clamp(x, c.rect.x, c.rect.x + c.rect.w), ny = clamp(y, c.rect.y, c.rect.y + c.rect.h);
556:       if ((x - nx) ** 2 + (y - ny) ** 2 < r * r) return false;
557:     } else if ((x - c.x) ** 2 + (y - c.y) ** 2 < (c.r + r * .75) ** 2) return false;
558:   }
559:   return true;
560: }
561: 
562: export function pointInWater(region, x, y) {
563:   const t = tileAt(region, x, y);
564:   return t === TERRAIN.WATER;
565: }

