  // exclamation / marker
  if (npc.marker) {
    const bob = Math.sin(time * 3 + npc.x) * 3;
    ctx.fillStyle = '#ffe6a0'; ctx.font = 'bold 18px Georgia'; ctx.textAlign = 'center';
    ctx.shadowColor = '#000'; ctx.shadowBlur = 6;
