:root{
  --gold:#e6bd6d; --gold-bright:#ffe9b0; --gold-dim:#a8823f;
  --ink:#080a12; --ink-2:#0d1120; --panel:rgba(12,16,30,.88); --panel-solid:#121728;
  --line:rgba(230,189,109,.26); --line-strong:rgba(230,189,109,.55);
  --text:#f3ecdd; --muted:#a6adbd; --faint:#6d7589;
  --red:#e45d62; --red-deep:#7d1e2a; --blue:#6f96ef; --blue-deep:#263b78;
  --green:#6fd0a8; --violet:#b18cff; --orange:#f28c4b;
  --serif:"Palatino Linotype","Book Antiqua",Palatino,Georgia,"Times New Roman",serif;
  --sans:"Avenir Next","Segoe UI",system-ui,-apple-system,sans-serif;
  --safe-t:env(safe-area-inset-top,0px); --safe-b:env(safe-area-inset-bottom,0px);
  --safe-l:env(safe-area-inset-left,0px); --safe-r:env(safe-area-inset-right,0px);
}
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%;overflow:hidden;background:#05060b;color:var(--text);font-family:var(--sans);-webkit-user-select:none;user-select:none;-webkit-tap-highlight-color:transparent;overscroll-behavior:none}
body{touch-action:none}
#app{position:fixed;inset:0;overflow:hidden;background:#05060b}
canvas#game{position:absolute;inset:0;width:100%;height:100%;display:block;background:#05060b;object-fit:contain;image-rendering:auto;cursor:crosshair}
.hidden{display:none!important}
button{font-family:inherit;color:inherit;background:none;border:0;cursor:pointer}
kbd{display:inline-flex;align-items:center;justify-content:center;min-width:22px;height:22px;padding:0 6px;border:1px solid rgba(255,255,255,.28);border-radius:5px;font:600 11px/1 var(--sans);color:#fff;background:rgba(255,255,255,.08);box-shadow:0 1px 0 rgba(255,255,255,.08) inset}
.glass{background:linear-gradient(160deg,rgba(20,26,44,.9),rgba(9,12,23,.92));border:1px solid var(--line);box-shadow:0 10px 34px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.06);backdrop-filter:blur(14px)}

