.ability:hover{border-color:var(--gold);transform:translateY(-2px)}
.ability:active{transform:translateY(0)}
.ability-key{position:absolute;top:3px;left:5px;font-size:8px;font-weight:700;color:rgba(255,255,255,.62)}
.ability-icon{width:30px;height:30px;margin-top:4px;margin-bottom:1px;position:relative}
.ability span{font-size:6.6px;letter-spacing:.08em;color:#cfd5e2;text-transform:uppercase;text-align:center;line-height:1.1;max-width:56px}
.ability .cooldown{position:absolute;inset:0;background:rgba(4,6,12,.72);color:#fff;display:none;place-items:center;font-size:15px;font-weight:800}
.ability.cooling .cooldown{display:grid}
.ico-sword::before{content:"";position:absolute;left:50%;top:0;width:5px;height:24px;transform:translateX(-50%) rotate(38deg);background:linear-gradient(180deg,#fff7d8,#bd9a55);clip-path:polygon(50% 0,100% 18%,100% 78%,50% 100%,0 78%,0 18%);box-shadow:0 0 8px rgba(255,231,160,.6)}
.ico-sword::after{content:"";position:absolute;left:50%;top:22px;width:17px;height:3px;transform:translateX(-50%) rotate(38deg);background:#8d6a38}
.ico-wave::before{content:"";position:absolute;inset:4px;border:2px solid #ffdf9a;border-radius:50% 50% 50% 50%/60% 60% 40% 40%;border-left-color:transparent;border-bottom-color:transparent;transform:rotate(-30deg);box-shadow:0 0 10px rgba(255,220,140,.4)}
.ico-wave::after{content:"";position:absolute;inset:10px;border:1px solid #fff2c9;border-radius:50%;border-right-color:transparent;border-top-color:transparent;transform:rotate(140deg)}
.ico-pulse::before{content:"";position:absolute;inset:3px;border-radius:50%;border:1px solid #a8a0ff;box-shadow:0 0 10px rgba(160,150,255,.5),inset 0 0 8px rgba(160,150,255,.4)}
.ico-pulse::after{content:"";position:absolute;inset:11px;border-radius:50%;background:radial-gradient(circle,#e5e0ff,#8b7cff 60%,transparent 70%)}
.ico-step::before{content:"";position:absolute;inset:5px;border:2px dashed #8fd5ff;border-radius:50%;transform:rotate(15deg)}
.ico-step::after{content:"✦";position:absolute;inset:0;display:grid;place-items:center;color:#c5ecff;font-size:16px}
.companion-ability{width:76px;border-color:rgba(140,210,255,.25)}
.companion-ability .ability-icon{width:26px;height:26px;border-radius:50%;background:radial-gradient(circle at 40% 35%,#9ee6ff,#4f7fae 70%,#1b2d44)}
.creature-party{position:absolute;right:calc(20px + var(--safe-r));bottom:calc(98px + var(--safe-b));display:flex;gap:8px;align-items:center;padding:7px 12px 7px 7px;border-radius:8px;pointer-events:none;min-width:150px}
#party-icon{width:42px;height:42px;border-radius:50%;background:radial-gradient(circle at 40% 35%,#2e3d61,#0b111f);border:1px solid rgba(140,210,255,.35)}
.party-text{display:flex;flex-direction:column;gap:4px}
.party-text span{font-size:8px;letter-spacing:.14em;color:#a9d9f5}
.party-hp{width:78px;height:4px;background:rgba(0,0,0,.6);border-radius:2px;overflow:hidden}
.party-hp i{display:block;height:100%;width:100%;background:linear-gradient(90deg,#5be0c0,#9ef5d7)}
.interaction,.resonate-prompt{position:absolute;left:50%;top:62%;transform:translateX(-50%);display:flex;align-items:center;gap:9px;padding:8px 16px;background:rgba(8,11,20,.86);border:1px solid rgba(230,189,109,.38);border-radius:20px;font-size:11px;letter-spacing:.08em;color:#f4ecd9;animation:floatPulse 2s ease-in-out infinite}
.resonate-prompt{border-color:rgba(170,150,255,.55);box-shadow:0 0 24px rgba(140,120,255,.25)}
.resonate-prompt kbd{border-color:rgba(180,160,255,.6)}
@keyframes floatPulse{0%,100%{transform:translateX(-50%) translateY(0)}50%{transform:translateX(-50%) translateY(-4px)}}
.toast-stack{position:absolute;left:50%;top:calc(18px + var(--safe-t));transform:translateX(-50%);display:flex;flex-direction:column;gap:7px;align-items:center;z-index:4}
.toast{padding:7px 18px;border-radius:20px;background:rgba(8,12,22,.9);border:1px solid rgba(230,189,109,.3);font-size:10.5px;letter-spacing:.1em;color:#f1e7d2;animation:toastIn .3s ease both,toastOut .4s ease 2.7s both;white-space:nowrap;box-shadow:0 8px 26px rgba(0,0,0,.45)}
.toast.gold{border-color:rgba(255,215,130,.6);color:#ffe9b0}
.toast.creature{border-color:rgba(160,180,255,.6);color:#cfd8ff;box-shadow:0 0 26px rgba(120,140,255,.25)}
.toast.danger{border-color:rgba(255,110,110,.55);color:#ffc0c0}
@keyframes toastIn{from{opacity:0;transform:translateY(-8px) scale(.96)}to{opacity:1;transform:none}}
@keyframes toastOut{to{opacity:0;transform:translateY(-5px)}}
.zone-banner{position:absolute;left:50%;top:38%;transform:translateX(-50%);text-align:center;pointer-events:none;animation:zoneIn 4.2s ease both}
.zone-line{width:min(280px,36vw);height:1px;background:linear-gradient(90deg,transparent,rgba(230,189,109,.8),transparent);margin:8px auto}
.zone-name{font-family:var(--serif);font-size:clamp(28px,4vw,48px);letter-spacing:.34em;text-indent:.34em;color:#fff1ce;text-shadow:0 4px 30px rgba(0,0,0,.9)}
.zone-sub{font-size:9px;letter-spacing:.3em;color:#d3b77e;margin-top:4px}
@keyframes zoneIn{0%{opacity:0;transform:translateX(-50%) translateY(10px)}12%,78%{opacity:1;transform:translateX(-50%) translateY(0)}100%{opacity:0;transform:translateX(-50%) translateY(-8px)}}
.desktop-hints{position:absolute;left:calc(50% + 80px);bottom:calc(2px + var(--safe-b));display:flex;gap:11px;font-size:8px;color:rgba(210,214,226,.4);letter-spacing:.06em;pointer-events:none;white-space:nowrap}
.desktop-hints span{display:flex;gap:4px;align-items:center}
.desktop-hints kbd{height:17px;min-width:17px;font-size:8px}

---TAIL---
@keyframes blinkArrow{0%,100%{transform:translateX(0);opacity:.6}50%{transform:translateX(3px);opacity:1}}

/* ============ RESONANCE ============ */
.resonance-screen{background:radial-gradient(ellipse at 50% 45%,rgba(30,36,80,.88),rgba(4,5,12,.97) 72%);z-index:44}
.resonance-panel{text-align:center;width:min(480px,92vw);display:flex;flex-direction:column;align-items:center}
.resonance-kicker{font-size:8px;letter-spacing:.4em;color:#9b8cf0;margin-bottom:6px}
.resonance-panel h2{font-family:var(--serif);font-weight:400;font-size:26px;letter-spacing:.08em;color:#e8e4ff;text-shadow:0 0 26px rgba(140,120,255,.5);margin-bottom:2px}
.resonance-ring-wrap{position:relative;width:min(360px,78vw);aspect-ratio:1;margin:10px 0 4px}
#resonance-canvas{width:100%;height:100%;display:block;filter:drop-shadow(0 0 24px rgba(140,120,255,.25))}
.resonance-center{position:absolute;inset:0;display:grid;place-items:center;font-size:34px;color:#dcd6ff;text-shadow:0 0 24px #8d7cff;animation:centerPulse 1.8s ease-in-out infinite}
@keyframes centerPulse{0%,100%{transform:scale(1);opacity:.7}50%{transform:scale(1.12);opacity:1}}
.resonance-copy{font-size:10.5px;line-height:1.55;color:#a8a8c8;margin-bottom:12px}
.resonance-copy kbd{margin:0 3px}
.resonance-meter{width:70%;height:5px;border-radius:3px;background:rgba(255,255,255,.08);overflow:hidden;margin-bottom:16px}
#res-fill{height:100%;width:0%;background:linear-gradient(90deg,#7566e0,#b9a8ff,#ffe6a8);transition:width .1s}
#res-strike{min-width:200px}

/* ============ CUTSCENE ============ */
.cutscene{background:#05060b;z-index:50;overflow:hidden}
.cutscene-bg{position:absolute;inset:-5%;background-size:cover;background-position:center;filter:blur(2px) saturate(.8);transform:scale(1.05);opacity:.8;transition:opacity 1s}
.cutscene-bg::after{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at 50% 45%,transparent 5%,rgba(3,5,10,.82) 75%)}
.cutscene-content{position:relative;z-index:2;text-align:center;width:min(700px,88vw);display:flex;flex-direction:column;align-items:center;animation:fadeUp 1s ease both}
.cutscene-chapter{font-size:9px;letter-spacing:.5em;color:var(--gold);margin-bottom:10px}
.cutscene-content h2{font-family:var(--serif);font-weight:400;font-size:clamp(32px,5vw,60px);letter-spacing:.06em;color:#fff1d2;text-shadow:0 4px 30px #000;line-height:1.05}
.cutscene-rule{display:flex;align-items:center;gap:10px;color:var(--gold);font-size:10px;margin:16px 0;width:220px}
.cutscene-rule i{flex:1;height:1px;background:linear-gradient(90deg,transparent,var(--gold))}
.cutscene-rule i:last-child{transform:rotate(180deg)}
.cutscene-content p{font-family:var(--serif);font-size:clamp(13px,1.5vw,17px);line-height:1.8;color:#c9cbd6;font-style:italic;min-height:80px}
#cutscene-skip{margin-top:22px;font-size:9px;padding:10px 20px}
.rotate{position:fixed;inset:0;z-index:200;background:#070a12;display:none;flex-direction:column;align-items:center;justify-content:center;gap:10px;text-align:center;padding:30px}
.rotate-glyph{font-size:54px;color:var(--gold);animation:rotateHint 2.4s ease-in-out infinite}
@keyframes rotateHint{0%,100%{transform:rotate(0)}50%{transform:rotate(90deg)}}
.rotate p{font-family:var(--serif);font-size:22px;color:#ffe8b6}
.rotate span{font-size:10px;color:var(--muted);letter-spacing:.08em}
.fatal{position:fixed;inset:0;z-index:300;background:#0a0c14;color:#f0e5cf;padding:40px;font:14px/1.6 monospace;white-space:pre-wrap;overflow:auto}

/* Scrollbars */
::-webkit-scrollbar{width:7px;height:7px}
::-webkit-scrollbar-track{background:rgba(255,255,255,.02)}
::-webkit-scrollbar-thumb{background:rgba(230,189,109,.22);border-radius:4px}
::-webkit-scrollbar-thumb:hover{background:rgba(230,189,109,.4)}

/* ============ RESPONSIVE MENUS ============ */
@media (max-width:880px){
  .creation-body{grid-template-columns:1fr;gap:14px}
  .creation-preview{min-height:200px;order:-1}
  #creation-canvas{max-width:240px}
  .preview-caption,.preview-plinth{display:none}
  .creation-wrap{padding:14px}
  .creation-head h2{font-size:20px}
  .creation-foot{position:sticky;bottom:0;background:linear-gradient(0deg,#070a12 70%,transparent);padding:12px 0}
  .overlay-panel{height:94vh;width:96vw}
  .overlay-body{padding:14px 16px}
  .overlay-head{padding:14px 16px 10px}
  .overlay-head h2{font-size:21px}
  .menu-grid,.shop-grid,.equip-layout,.map-wrap{grid-template-columns:1fr}
  .menu-detail{min-height:auto}
  .menu-list{flex-direction:row;overflow-x:auto;padding-bottom:4px}
  .menu-list button{white-space:nowrap;padding:9px 12px;font-size:9px}
  .dialogue-box{min-height:120px;padding:10px;gap:10px}
  #dialogue-portrait{width:76px;height:76px}
  .dialogue-name{font-size:15px}
  .dialogue-text{font-size:11px;line-height:1.5}
  .dialogue-role{font-size:6.5px}
  .ability-bar{display:none}
  .touch-controls:not(.hidden){display:block}
  .desktop-hints{display:none}
  .stat-grid{grid-template-columns:1fr}
  .gear-cards{grid-template-columns:1fr}
  .overlay-foot{font-size:7px}
}
@media (max-height:560px){
  .vitals{transform:scale(.86);transform-origin:top left}
  .minimap{width:92px;height:92px}
  .quest-tracker{top:calc(96px + var(--safe-t))}
  .creation-preview{min-height:150px}
  #creation-canvas{max-width:190px}
  .dialogue-box{min-height:100px}
  #dialogue-portrait{width:64px;height:64px}
}

/* ============ TOUCH ============ */
.touch-controls{display:none;position:absolute;inset:0;pointer-events:none;z-index:3}
.joystick{position:absolute;left:calc(18px + var(--safe-l));bottom:calc(24px + var(--safe-b));width:118px;height:118px;border-radius:50%;border:1px solid rgba(230,189,109,.3);background:radial-gradient(circle,rgba(20,26,44,.65),rgba(8,11,20,.3));pointer-events:auto;touch-action:none;backdrop-filter:blur(4px)}
.stick{position:absolute;left:50%;top:50%;width:52px;height:52px;margin:-26px 0 0 -26px;border-radius:50%;background:radial-gradient(circle at 40% 35%,rgba(255,240,200,.55),rgba(140,110,60,.45));border:1px solid rgba(255,230,170,.5);box-shadow:0 4px 18px rgba(0,0,0,.45)}
.touch-actions{position:absolute;right:calc(14px + var(--safe-r));bottom:calc(20px + var(--safe-b));display:grid;grid-template-columns:repeat(4,1fr);gap:8px;pointer-events:auto;width:292px}
.tbtn{height:58px;border-radius:50%;border:1px solid rgba(230,189,109,.4);background:radial-gradient(circle at 40% 30%,rgba(50,60,88,.85),rgba(12,16,28,.88));font:700 10px/1 var(--sans);letter-spacing:.06em;color:#eee4cf;touch-action:none;box-shadow:0 4px 14px rgba(0,0,0,.35),inset 0 1px 0 rgba(255,255,255,.1)}
.tbtn:active{background:rgba(230,189,109,.28);transform:scale(.96)}
.tbtn.attack{background:radial-gradient(circle at 40% 30%,#a8593c,#561d22);border-color:rgba(255,150,110,.5);font-size:11px}
.tbtn.dodge{background:radial-gradient(circle at 40% 30%,#3f5b86,#17243d);border-color:rgba(130,180,255,.45);font-size:8px}
.tbtn.small{height:46px;font-size:10px}
.tbtn.skill{font-size:10px;border-color:rgba(160,150,255,.3)}
@media (pointer:coarse){#game{cursor:default}}
@media (max-width:1020px){
  .vitals{min-width:260px;padding:8px 12px 8px 8px;gap:9px}
  .portrait-wrap{width:52px;height:52px}
  .minimap{width:118px;height:118px}
  .quest-tracker{top:calc(148px + var(--safe-t));width:200px;padding:10px 12px}
  .quest-name{font-size:13px}
  .quest-objective{font-size:9.5px}
  .ability-bar{bottom:calc(8px + var(--safe-b));gap:5px;padding:6px}
  .ability{width:54px;height:54px}
  .ability span{font-size:5.8px}
  .desktop-hints{display:none}
  .creature-party{display:none}
  .boss-bar{bottom:calc(88px + var(--safe-b));width:56vw}
  .touch-controls:not(.hidden){display:block}
  .desktop-hints{display:none}
}
@media (max-width:760px){
  .title-menu{flex-direction:column;gap:9px;margin-top:3.2vh}
  .btn-primary,.btn-ghost{padding:12px 22px;font-size:10px}
  .minimap{width:92px;height:92px}
  .vitals{min-width:220px}
  .char-line{font-size:12px}
  .ability-bar{display:none}
  .quest-tracker{width:172px;top:calc(116px + var(--safe-t));padding:8px 10px}
  .quest-kicker{font-size:6px}
  .quest-name{font-size:11px}
  .quest-objective{font-size:8px}
  .boss-bar{width:62vw;bottom:calc(82px + var(--safe-b))}
  .boss-name{font-size:14px}
  .title-foot{display:none}
}
@media (orientation:portrait) and (max-width:900px){
  .rotate{display:flex!important}
}

/* ============ CREATION ============ */
.creation-screen{background:radial-gradient(ellipse at 35% 40%,rgba(27,36,60,.92),rgba(5,7,13,.97) 70%);backdrop-filter:blur(4px);align-items:stretch;justify-content:stretch;overflow:auto}
.creation-wrap{width:100%;max-width:1180px;margin:auto;padding:calc(20px + var(--safe-t)) 28px calc(20px + var(--safe-b));display:flex;flex-direction:column;gap:16px;min-height:100%}
.creation-head{display:flex;justify-content:space-between;align-items:flex-end;border-bottom:1px solid var(--line);padding-bottom:14px}
.eyebrow{font-size:8px;letter-spacing:.34em;color:var(--gold);margin-bottom:5px}
.creation-head h2{font-family:var(--serif);font-weight:400;font-size:clamp(21px,2.8vw,32px);letter-spacing:.05em;color:#fff2d8}
.creation-step{font-size:8px;letter-spacing:.26em;color:var(--faint)}
.creation-body{display:grid;grid-template-columns:390px 1fr;gap:28px;flex:1;min-height:0}
.creation-preview{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;border:1px solid rgba(230,189,109,.16);border-radius:10px;background:radial-gradient(ellipse at 50% 40%,rgba(53,70,108,.5),rgba(10,13,24,.6) 68%);overflow:hidden}
.creation-preview::before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(0deg,transparent 0 3px,rgba(255,255,255,.014) 3px 4px);pointer-events:none}
#creation-canvas{width:100%;max-width:400px;aspect-ratio:420/480;display:block;position:relative;z-index:1}
.preview-plinth{position:absolute;bottom:13%;width:56%;height:14px;border-radius:50%;background:radial-gradient(ellipse,rgba(230,189,109,.25),transparent 70%);filter:blur(4px)}
.preview-caption{position:absolute;bottom:10px;font-size:7px;letter-spacing:.34em;color:rgba(230,189,109,.55)}
.creation-options{display:flex;flex-direction:column;min-height:0}
.creation-tabs{display:flex;gap:2px;border-bottom:1px solid rgba(230,189,109,.2);margin-bottom:16px}
.ctab{font-size:9px;letter-spacing:.2em;padding:10px 16px;color:var(--faint);border-bottom:2px solid transparent;transition:.15s}
.ctab:hover{color:#e6d8bd}
.ctab.active{color:var(--gold-bright);border-bottom-color:var(--gold)}
.ctab-panel{overflow:auto;padding-right:6px;flex:1;scrollbar-width:thin}
.field{display:flex;flex-direction:column;gap:5px;font-size:8px;letter-spacing:.18em;color:var(--muted);margin-bottom:14px}
.field input{font-family:var(--serif);font-size:18px;letter-spacing:.04em;color:#fff2d8;background:rgba(0,0,0,.3);border:1px solid rgba(230,189,109,.28);border-radius:5px;padding:9px 12px;outline:none;transition:.15s}
.field input:focus{border-color:var(--gold);box-shadow:0 0 0 3px rgba(230,189,109,.1)}
.opt-row{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:8px 0;border-bottom:1px solid rgba(255,255,255,.05)}
.opt-row>span{font-size:9px;letter-spacing:.12em;color:var(--muted);white-space:nowrap}
.opt-buttons{display:flex;gap:4px;flex-wrap:wrap;justify-content:flex-end}
.opt-buttons button{font-size:9px;letter-spacing:.05em;padding:6px 10px;border:1px solid rgba(255,255,255,.1);border-radius:4px;color:#a8afbf;background:rgba(255,255,255,.03)}
.opt-buttons button:hover{border-color:rgba(230,189,109,.4);color:#eadfc8}
.opt-buttons button.sel{background:rgba(230,189,109,.16);border-color:rgba(230,189,109,.6);color:#ffe9b0}
.swatches{display:flex;gap:7px}
.swatches button{width:24px;height:24px;border-radius:50%;background:var(--c);border:2px solid rgba(0,0,0,.4);box-shadow:0 0 0 1px rgba(255,255,255,.2);transition:.15s}
.swatches button.sel{box-shadow:0 0 0 2px var(--gold),0 0 12px rgba(230,189,109,.4);transform:scale(1.08)}
.panel-copy{font-size:11px;line-height:1.55;color:#9ea7ba;margin-bottom:14px}
.panel-copy strong{color:var(--gold)}
.stat-alloc-list{display:grid;gap:7px}
.stat-row{display:grid;grid-template-columns:1fr 110px 28px;align-items:center;gap:8px;padding:7px 10px;border:1px solid rgba(255,255,255,.07);border-radius:5px;background:rgba(255,255,255,.018)}
.stat-row .sname{font-size:10px;letter-spacing:.06em;color:#ddd5c5}
.stat-row .sdesc{font-size:8px;color:var(--faint);display:block;margin-top:2px}
.stat-bar{display:flex;gap:3px}
.stat-bar i{display:block;flex:1;height:5px;border-radius:1px;background:rgba(255,255,255,.09)}
.stat-bar i.on{background:linear-gradient(90deg,#c99a4d,#f0d18a);box-shadow:0 0 6px rgba(230,189,109,.35)}
.stat-plus{width:24px;height:24px;border-radius:50%;border:1px solid rgba(230,189,109,.4);color:var(--gold);font-size:14px;line-height:1;display:grid;place-items:center}
.stat-plus:hover{background:rgba(230,189,109,.16)}
.stat-plus:disabled{opacity:.2;pointer-events:none}
.stat-points{font-size:9px;letter-spacing:.1em;color:var(--muted);margin-top:13px;text-align:right}
.stat-points strong{color:var(--gold);font-size:14px}
.gear-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-bottom:14px}
.gear-card{position:relative;padding:13px 11px;border:1px solid rgba(255,255,255,.09);border-radius:6px;background:rgba(255,255,255,.025);text-align:left;transition:.15s}
.gear-card:hover{border-color:rgba(230,189,109,.35)}
.gear-card.sel{border-color:var(--gold);background:rgba(230,189,109,.08);box-shadow:0 0 18px rgba(230,189,109,.1)}
.gear-card b{display:block;font-family:var(--serif);font-size:14px;font-weight:400;color:#fff0d0;margin-bottom:3px}
.gear-card em{display:block;font-style:normal;font-size:8px;letter-spacing:.1em;color:var(--gold);margin-bottom:6px}
.gear-card span{font-size:9px;line-height:1.4;color:#9099ac;display:block}
.signature-preview{font-size:9.5px;line-height:1.55;color:#aab2c2;border-left:2px solid rgba(230,189,109,.35);padding:7px 12px;background:rgba(0,0,0,.18)}
.creation-foot{display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--line);padding-top:14px}
.creation-dots{display:flex;gap:6px}
.creation-dots i{width:5px;height:5px;border-radius:50%;background:rgba(255,255,255,.16)}
.creation-dots i.active{background:var(--gold);box-shadow:0 0 8px var(--gold)}

/* ============ OVERLAY / MENUS ============ */
#overlay{background:rgba(3,5,10,.78);backdrop-filter:blur(8px);z-index:40}
.overlay-panel{width:min(1040px,94vw);height:min(720px,92vh);display:flex;flex-direction:column;background:linear-gradient(165deg,rgba(18,23,40,.98),rgba(7,9,18,.99));border:1px solid rgba(230,189,109,.3);border-radius:10px;box-shadow:0 30px 90px rgba(0,0,0,.7);overflow:hidden;animation:panelIn .22s ease}
@keyframes panelIn{from{opacity:0;transform:scale(.985) translateY(8px)}to{opacity:1;transform:none}}
.overlay-head{display:flex;justify-content:space-between;align-items:flex-end;padding:20px 26px 14px;border-bottom:1px solid var(--line);background:radial-gradient(ellipse at 10% 0%,rgba(230,189,109,.08),transparent 60%)}
.overlay-head h2{font-family:var(--serif);font-weight:400;font-size:28px;color:#fff0d3;letter-spacing:.04em}
.close-btn{width:34px;height:34px;border-radius:50%;border:1px solid rgba(255,255,255,.14);color:#bcc2cf;font-size:14px;transition:.15s}
.close-btn:hover{background:rgba(230,189,109,.14);border-color:var(--gold);color:#fff}
.overlay-tabs{display:flex;gap:2px;padding:0 20px;border-bottom:1px solid rgba(255,255,255,.06);overflow-x:auto;scrollbar-width:none}
.overlay-tabs::-webkit-scrollbar{display:none}
.otab{font-size:9px;letter-spacing:.16em;padding:11px 14px;color:var(--faint);border-bottom:2px solid transparent;white-space:nowrap}
.otab.active{color:var(--gold-bright);border-bottom-color:var(--gold)}
.otab:hover{color:#ddd3c1}
.overlay-body{padding:18px 26px;overflow:auto;flex:1;scrollbar-width:thin;scrollbar-color:rgba(230,189,109,.3) transparent}
.overlay-foot{padding:11px 26px;border-top:1px solid rgba(255,255,255,.06);display:flex;justify-content:space-between;align-items:center;font-size:8px;letter-spacing:.14em;color:var(--faint);background:rgba(0,0,0,.17);min-height:44px}
.menu-grid{display:grid;grid-template-columns:280px 1fr;gap:18px}
.menu-list{display:flex;flex-direction:column;gap:5px}
.menu-list button{display:flex;align-items:center;gap:10px;padding:12px 14px;border-radius:5px;border:1px solid transparent;text-align:left;font-size:10.5px;letter-spacing:.05em;color:#aab2c4}
.menu-list button:hover{background:rgba(255,255,255,.04);color:#e9e0cf}
.menu-list button.active{background:rgba(230,189,109,.11);border-color:rgba(230,189,109,.28);color:#ffe8b4}
.menu-list button .mi{width:16px;text-align:center;color:var(--gold);opacity:.8}
.menu-detail{min-height:400px}
.panel-card{border:1px solid rgba(255,255,255,.08);border-radius:7px;padding:15px 17px;background:rgba(255,255,255,.02);margin-bottom:11px}
.panel-card h3{font-family:var(--serif);font-weight:400;font-size:18px;color:#f8ecd5;margin-bottom:4px;letter-spacing:.03em}
.panel-card .sub{font-size:8px;letter-spacing:.18em;color:var(--gold);margin-bottom:9px}
---HUD-MOBILE---
.resonance-copy kbd{margin:0 3px}
.resonance-meter{width:70%;height:5px;border-radius:3px;background:rgba(255,255,255,.08);overflow:hidden;margin-bottom:16px}
#res-fill{height:100%;width:0%;background:linear-gradient(90deg,#7566e0,#b9a8ff,#ffe6a8);transition:width .1s}
#res-strike{min-width:200px}

/* ============ CUTSCENE ============ */
.cutscene{background:#05060b;z-index:50;overflow:hidden}
.cutscene-bg{position:absolute;inset:-5%;background-size:cover;background-position:center;filter:blur(2px) saturate(.8);transform:scale(1.05);opacity:.8;transition:opacity 1s}
.cutscene-bg::after{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at 50% 45%,transparent 5%,rgba(3,5,10,.82) 75%)}
.cutscene-content{position:relative;z-index:2;text-align:center;width:min(700px,88vw);display:flex;flex-direction:column;align-items:center;animation:fadeUp 1s ease both}
.cutscene-chapter{font-size:9px;letter-spacing:.5em;color:var(--gold);margin-bottom:10px}
.cutscene-content h2{font-family:var(--serif);font-weight:400;font-size:clamp(32px,5vw,60px);letter-spacing:.06em;color:#fff1d2;text-shadow:0 4px 30px #000;line-height:1.05}
.cutscene-rule{display:flex;align-items:center;gap:10px;color:var(--gold);font-size:10px;margin:16px 0;width:220px}
.cutscene-rule i{flex:1;height:1px;background:linear-gradient(90deg,transparent,var(--gold))}
.cutscene-rule i:last-child{transform:rotate(180deg)}
.cutscene-content p{font-family:var(--serif);font-size:clamp(13px,1.5vw,17px);line-height:1.8;color:#c9cbd6;font-style:italic;min-height:80px}
#cutscene-skip{margin-top:22px;font-size:9px;padding:10px 20px}
.rotate{position:fixed;inset:0;z-index:200;background:#070a12;display:none;flex-direction:column;align-items:center;justify-content:center;gap:10px;text-align:center;padding:30px}
.rotate-glyph{font-size:54px;color:var(--gold);animation:rotateHint 2.4s ease-in-out infinite}
@keyframes rotateHint{0%,100%{transform:rotate(0)}50%{transform:rotate(90deg)}}
.rotate p{font-family:var(--serif);font-size:22px;color:#ffe8b6}
.rotate span{font-size:10px;color:var(--muted);letter-spacing:.08em}
.fatal{position:fixed;inset:0;z-index:300;background:#0a0c14;color:#f0e5cf;padding:40px;font:14px/1.6 monospace;white-space:pre-wrap;overflow:auto}

/* Scrollbars */
::-webkit-scrollbar{width:7px;height:7px}
::-webkit-scrollbar-track{background:rgba(255,255,255,.02)}
::-webkit-scrollbar-thumb{background:rgba(230,189,109,.22);border-radius:4px}
::-webkit-scrollbar-thumb:hover{background:rgba(230,189,109,.4)}

/* ============ RESPONSIVE MENUS ============ */
@media (max-width:880px){
  .creation-body{grid-template-columns:1fr;gap:14px}
  .creation-preview{min-height:200px;order:-1}
  #creation-canvas{max-width:240px}
  .preview-caption,.preview-plinth{display:none}
  .creation-wrap{padding:14px}
  .creation-head h2{font-size:20px}
  .creation-foot{position:sticky;bottom:0;background:linear-gradient(0deg,#070a12 70%,transparent);padding:12px 0}
  .overlay-panel{height:94vh;width:96vw}
  .overlay-body{padding:14px 16px}
  .overlay-head{padding:14px 16px 10px}
  .overlay-head h2{font-size:21px}
  .menu-grid,.shop-grid,.equip-layout,.map-wrap{grid-template-columns:1fr}
  .menu-detail{min-height:auto}
  .menu-list{flex-direction:row;overflow-x:auto;padding-bottom:4px}
  .menu-list button{white-space:nowrap;padding:9px 12px;font-size:9px}
  .dialogue-box{min-height:120px;padding:10px;gap:10px}
  #dialogue-portrait{width:76px;height:76px}
  .dialogue-name{font-size:15px}
  .dialogue-text{font-size:11px;line-height:1.5}
  .dialogue-role{font-size:6.5px}
  .ability-bar{display:none}
  .touch-controls:not(.hidden){display:block}
  .desktop-hints{display:none}
  .stat-grid{grid-template-columns:1fr}
  .gear-cards{grid-template-columns:1fr}
  .overlay-foot{font-size:7px}
}
@media (max-height:560px){
  .vitals{transform:scale(.86);transform-origin:top left}
  .minimap{width:92px;height:92px}
  .quest-tracker{top:calc(96px + var(--safe-t))}
  .creation-preview{min-height:150px}
  #creation-canvas{max-width:190px}
  .dialogue-box{min-height:100px}
  #dialogue-portrait{width:64px;height:64px}
}

