  ctx.fillStyle = '#4a3020'; ctx.beginPath(); ctx.ellipse(x, y, 16, 5, 0, 0, 6.3); ctx.fill();
  poly(ctx, [[x - 9, y], [x + fl, y - 24], [x + 8, y]], color, null);
  poly(ctx, [[x - 4, y], [x + fl * .6, y - 16], [x + 4, y]], '#ffe6a0', null);
}

