  for (let a = 0; a < 10; a++) {
    const ang = a / 10 * Math.PI * 2;
    b.addProp('standing_stone', 40 + Math.cos(ang) * 7.3, 78 + Math.sin(ang) * 6.2, { collide: .55, seed: rng(), scale: .9 + rng() * .3 });
