src/data/story.js:588:    { chapter: 'VALDORIA', title: 'Aldea de Lumen', text: 'Tres noches antes de tu despertar, los niños de la aldea empezaron a oír una canción bajo la tierra. Los ancianos dijeron que era el Velo. Los sabios dijeron que era el fin. Ninguno se equivocaba.', bg: 'var(--cut-bg-3)' }
src/data/story.js:591:    { chapter: 'CAPÍTULO II', title: 'Drakmor', text: 'El Velo se abrió sobre un mar de ceniza. Aquí, donde la Primera Brasa tocó el mundo, la Gema dejó la única lágrima que una llama puede llorar.', bg: 'var(--cut-bg-4)' },
src/data/story.js:592:    { chapter: 'CAPÍTULO II', title: 'La Lágrima', text: 'Malachar, el último rey de Drakmor, la custodiaba. No para usarla. Para que nadie más la encontrara. Ahora la Lágrima late en tu mano, y el Coro ha empezado a cantar.', bg: 'var(--cut-bg-5)' }
src/data/story.js:595:    { chapter: 'CAPÍTULO III', title: 'Kansordore', text: 'Sobre las nubes, los templos del Coro flotan como notas suspendidas. Aquí se guarda la verdad que el Velo protege: el mundo no es un lugar. Es una canción que alguien está soñando.', bg: 'var(--cut-bg-6)' },
src/data/story.js:596:    { chapter: 'CAPÍTULO III', title: 'El Archivo del Velo', text: 'Veyra, la última custodio, te espera entre ecos de mundos que no fueron. La Profecía nunca incluyó tu nombre. Por eso puedes cambiarla.', bg: 'var(--cut-bg-7)' }
